static inline ll gcd(ll a, ll b) {
	for(; b > 0; a %= b, swap(a, b));
	return a;
}
static inline ll lcm(ll a, ll b) {
	return (a / gcd(a, b)) * b;
}
static inline ll power(ll a, ll b, ll p) {
	ll result = 1;
	for(; b > 0; b >>= 1, a = a * a % p) {
		if(b & 1) {
			result = result * a % p;
		}
	}
	return result;
}
static inline ll inverse(ll a, ll p) {
	return power(a, p - 2, p);
}

