/**
 * Dynamic Hash:
 *      A Polynomial Rolling Hash and Fenwick Tree
 *      based String Hashing Data Structure.
 * Operations Supported:
 *      int size() {
 *          returns the size of the hash (length of string)
 *      }
 *      pair<int, int> prefix(int index) {
 *          returns the hash of the prefix S[0, index]
 *      }
 *      pair<int, int> substr(int l, int r) {
 *          returns the hash of the substring S[l, r]
 *      }
 *      void update(int index, char source, char target) {
 *          Updates the hash value when S[index]
 *          is replaced from source to target
 *      }
 *      bool operator==(DynamicHash& other) {
 *          returns true if this == other
 *      }
 */
class DynamicHash {
private:
    // Constants
    const char OFFSET = 'a';    // Set this to 'A' if Upper-case
    const int P1 = 31, P2 = 37; // Other options: (1571, 1597), (107897, 126271)
    const int MOD1 = 1e9 + 7, MOD2 = 1e9 + 9;
    const int INV_P1 = inverse(P1, MOD1), INV_P2 = inverse(P2, MOD2);

    // Hash size
    int length = 0;

    // Fenwick Tree members
    int bit_size;
    vector<int> bit1, bit2;

    // Fenwick Tree methods

    /**
     * Builds BIT for the Hash Vectors
     * Call this only when hash1 and hash2 are populated
     */
    void bit_build() {
        bit_size = length + 2;
        bit1.assign(bit_size, 0);
        bit2.assign(bit_size, 0);
        for (int i = 0; i < length; i++) {
            bit_add(bit1, i, hash1[i], MOD1);
            bit_add(bit2, i, hash2[i], MOD2);
        }
    }

    /**
     * Point Addition: Adds Val to the element at index Position
     */
    void bit_add(vector<int>& bit, int index, int val, int modulo) {
        for (++index; index < bit_size; index += index & -index) {
            // if val < 0: adding 2LL * modulo will make it positive
            bit[index] = (bit[index] + (2LL * modulo) + val) % modulo;
        }
    }

    /**
     * Range Query: Returns the Sum of the Prefix ending at index
     */
    pair<int, int> bit_get(int index) const {
        ll h1 = 0, h2 = 0;
        for (++index; index > 0; index -= index & -index) {
            h1 += bit1[index];
            h1 %= MOD1;
            h2 += bit2[index];
            h2 %= MOD2;
        }
        return {(int)h1, (int)h2};
    }
    // End of Fenwick Tree Methods

public:
    // Shared (Static) Members
    // Note: hash1 and hash2 are presumed to be shared but they aren't.
    // They are needed for building Fenwick Trees bit1 and bit2
    inline static vector<int> hash1;
    inline static vector<int> p_pow1 = vector<int>(1, 1);
    inline static vector<int> inv_pow1 = vector<int>(1, 1);

    inline static vector<int> hash2;
    inline static vector<int> p_pow2 = vector<int>(1, 1);
    inline static vector<int> inv_pow2 = vector<int>(1, 1);

    inline static int cache_size = 1; // cache_size always grows

    // Constructor
    DynamicHash(const string& s) {
        length = s.size();

        for (; cache_size < length; cache_size++) {
            p_pow1.push_back((p_pow1.back() * 1LL * P1) % MOD1);
            inv_pow1.push_back((inv_pow1.back() * 1LL * INV_P1) % MOD1);

            p_pow2.push_back((p_pow2.back() * 1LL * P2) % MOD2);
            inv_pow2.push_back((inv_pow2.back() * 1LL * INV_P2) % MOD2);
        }

        hash1.resize(cache_size);
        hash2.resize(cache_size);

        for (int i = 0; i < length; i++) {
            ll h1 = ((s[i] - OFFSET + 1) * 1LL * p_pow1[i]) % MOD1;
            ll h2 = ((s[i] - OFFSET + 1) * 1LL * p_pow2[i]) % MOD2;
            hash1[i] = h1;
            hash2[i] = h2;
        }

        // Do not call this before computing hash1 and hash2
        bit_build();
    }

    /**
     * Returns the size of the string or hash
     */
    int size() const {
        return length;
    }

    /**
     * Returns the Hash of the prefix s[0, index]
     */
    pair<int, int> prefix(const int index) const {
        // Can be a Private Method
        return bit_get(index);
    }

    /**
     * Returns the hash value of the substring s[l, r]
     */
    pair<int, int> substr(const int l, const int r) const {
        if(l == 0) {
            return prefix(r);
        }

        auto p_r = prefix(r);
        auto p_l = prefix(l - 1);

        int temp1 = p_r.first - p_l.first;
        int temp2 = p_r.second - p_l.second;

        temp1 += (temp1 < 0 ? MOD1 : 0); temp1 = (temp1 * 1LL * inv_pow1[l]) % MOD1;
        temp2 += (temp2 < 0 ? MOD2 : 0); temp2 = (temp2 * 1LL * inv_pow2[l]) % MOD2;

        return {temp1, temp2};
    }

    /**
     * Updates the hash value when s[index]
     * is replaced from source to target.
     * Remember to update your original string.
     */
    void update(const int index, const char source, const char target) {
        if (source == target) {
            return;
        }

        // Compute the difference for MOD1 (consider target vs source)
        int d1 = (target - source + MOD1) % MOD1;
        d1 = (d1 * 1LL * p_pow1[index]) % MOD1;

        // Compute the difference for MOD2 (consider target vs source)
        int d2 = (target - source + MOD2) % MOD2;
        d2 = (d2 * 1LL * p_pow2[index]) % MOD2;

        bit_add(bit1, index, d1, MOD1);
        bit_add(bit2, index, d2, MOD2);
    }

    bool operator==(const DynamicHash& other) {
        return prefix(size() - 1) == other.prefix(other.size() - 1);
    }
};


#include <functional>

// https://en.wikipedia.org/wiki/Splay_tree

#ifndef SPLAY_TREE
#define SPLAY_TREE

template<typename T, typename Comp = std::less<T>>
class splay_tree {
private:
  Comp comp;
  unsigned long p_size;

  struct node {
    node *left, *right;
    node *parent;
    T key;
    node(const T& init = T()) : left(nullptr), right(nullptr), parent(nullptr), key(init) { }
    ~node() {

    }
  } *root;

  void left_rotate(node *x) {
    node *y = x->right;
    if (y) {
      x->right = y->left;
      if (y->left) y->left->parent = x;
      y->parent = x->parent;
    }

    if (!x->parent) root = y;
    else if (x == x->parent->left) x->parent->left = y;
    else x->parent->right = y;
    if (y) y->left = x;
    x->parent = y;
  }

  void right_rotate(node *x) {
    node *y = x->left;
    if (y) {
      x->left = y->right;
      if (y->right) y->right->parent = x;
      y->parent = x->parent;
    }
    if (!x->parent) root = y;
    else if (x == x->parent->left) x->parent->left = y;
    else x->parent->right = y;
    if (y) y->right = x;
    x->parent = y;
  }

  void splay(node *x) {
    while (x->parent) {
      if (!x->parent->parent) {
        if (x->parent->left == x) right_rotate(x->parent);
        else left_rotate(x->parent);
      } else if (x->parent->left == x && x->parent->parent->left == x->parent) {
        right_rotate(x->parent->parent);
        right_rotate(x->parent);
      } else if (x->parent->right == x && x->parent->parent->right == x->parent) {
        left_rotate(x->parent->parent);
        left_rotate(x->parent);
      } else if (x->parent->left == x && x->parent->parent->right == x->parent) {
        right_rotate(x->parent);
        left_rotate(x->parent);
      } else {
        left_rotate(x->parent);
        right_rotate(x->parent);
      }
    }
  }

  void replace(node *u, node *v) {
    if (!u->parent) root = v;
    else if (u == u->parent->left) u->parent->left = v;
    else u->parent->right = v;
    if (v) v->parent = u->parent;
  }

  node* subtree_minimum(node *u) {
    while (u->left) u = u->left;
    return u;
  }

  node* subtree_maximum(node *u) {
    while (u->right) u = u->right;
    return u;
  }
public:
  splay_tree() : root(nullptr), p_size(0) { }

  void insert(const T &key) {
    node *z = root;
    node *p = nullptr;

    while (z) {
      p = z;
      if (comp(z->key, key)) z = z->right;
      else z = z->left;
    }

    z = new node(key);
    z->parent = p;

    if (!p) root = z;
    else if (comp(p->key, z->key)) p->right = z;
    else p->left = z;

    splay(z);
    p_size++;
  }

  node* find(const T &key) {
    node *z = root;
    while (z) {
      if (comp(z->key, key)) z = z->right;
      else if (comp(key, z->key)) z = z->left;
      else return z;
    }
    return nullptr;
  }

  void erase(const T &key) {
    node *z = find(key);
    if (!z) return;

    splay(z);

    if (!z->left) replace(z, z->right);
    else if (!z->right) replace(z, z->left);
    else {
      node *y = subtree_minimum(z->right);
      if (y->parent != z) {
        replace(y, y->right);
        y->right = z->right;
        y->right->parent = y;
      }
      replace(z, y);
      y->left = z->left;
      y->left->parent = y;
    }

    delete z;
    p_size--;
  }

/* //the alternative implementation
    void erase(const T &key) {
        node *z = find(key);
        if (!z) return;

        splay(z);

        node *s = z->left;
        node *t = z->right;
        delete z;

        node *sMax = NULL;
        if (s) {
            s->parent = NULL;
            sMax = subtree_maximum(s);
            splay(sMax);
            root = sMax;
        }
        if (t) {
            if (s)
                sMax->right = t;
            else
                root = t;
            t->parent = sMax;
        }

        p_size--;
    }
*/

  const T& minimum() { return subtree_minimum(root)->key; }
  const T& maximum() { return subtree_maximum(root)->key; }

  bool empty() const { return root == nullptr; }
  unsigned long size() const { return p_size; }
};

#endif // SPLAY_TREE

#include <iostream>
#include <fstream>
#include <string>
#include <vector>
using namespace std;

/* Prototypes */
void ParseFile(string, vector<bool>&, vector<string>&, vector<string>&);
void ShowList(vector<bool>, vector<string>, vector<string>);
void ShowMenu();
void AddTask(vector<bool>&, vector<string>&, vector<string>&);
void ToggleTask(vector<bool>&);
void RemoveTask(vector<bool>&, vector<string>&, vector<string>&);
void SaveFile(string, vector<bool>&, vector<string>&, vector<string>&);

/* Global Variables */
ifstream fileReader;
ofstream fileWriter;

/* Start of Program */
int main()
{
  // Declare 3 vectors to hold our data.
  vector<bool> myChecks;
  vector<string> myTasks;
  vector<string> myDates;

  // Open the to do file and store the data to the vector.
  ParseFile("todo.txt", myChecks, myTasks, myDates);

  // Run the program until user choose exit.
  while (true)
  {
    // Clear the console/terminal screen.
    if (system("CLS")) system("clear");

    // Show list and menu.
    ShowList(myChecks, myTasks, myDates);
    ShowMenu();

    // Get user's choice.
    cout << "Choice: ";
    int choice;
    cin >> choice;
    cin.ignore(1000, 10);
    cout << endl << endl;

    // Do things based on user's choice.
    switch (choice)
    {
      case 1: // Add task.
        AddTask(myChecks, myTasks, myDates);
        break;
      case 2: // Check/uncheck a task.
        ToggleTask(myChecks);
        break;
      case 3: // Remove a task.
        RemoveTask(myChecks, myTasks, myDates);
        break;
      case 4:
        return 0;
    }

    // Save to file after we're done with user action.
    SaveFile("todo.txt", myChecks, myTasks, myDates);
  }
}

void ParseFile(string fileName,
               vector<bool>& checks,
               vector<string>& tasks,
               vector<string>& dates)
{
  // Open the file.
  fileReader.open(fileName);

  // Iterate through each line from the file.
  string line;
  while (getline(fileReader, line))
  {
    // Declare 3 variables to hold our data.
    string check = line.substr(0, 1);
    string task = line.substr(4, line.length());
    string date = task.substr(task.find("| ") + 2, task.length());
    task = task.substr(0, task.find("|"));

    // Add the data to the vectors.
    if (check == "0")
    {
      checks.push_back(false);
    }
    else
    {
      checks.push_back(true);
    }
    tasks.push_back(task);
    dates.push_back(date);
  }

  // Close the file.
  fileReader.close();
}

void ShowList(vector<bool> checks,
               vector<string> tasks,
               vector<string> dates)
{
  for (int i = 0; i < checks.size(); i++)
  {
    // Output number so user can easily select tasks.
    cout << i + 1 << ". ";

    // Output the check mark.
    if (checks[i] == false)
    {
      cout << "[ ] ";
    }
    else
    {
      cout << "[x] ";
    }

    // Output the task description.
    cout << tasks[i] << endl;

    // Output the task date.
    cout << "       " << dates[i] << endl << endl;
  }
}

