using uiuc::PNG;
using uiuc::HSLAPixel;

/**
 * Returns an image that has been transformed to grayscale.
 *
 * The saturation of every pixel is set to 0, removing any color.
 *
 * @return The grayscale image.
 */
PNG grayscale(PNG image) {

  for (unsigned x = 0; x < image.width(); x++) {
    for (unsigned y = 0; y < image.height(); y++) {
      HSLAPixel & pixel = image.getPixel(x, y);

      // `pixel` is a reference to the memory stored inside of the PNG `image`,
      // which means you're changing the image directly. No need to `set`
      // the pixel since you're directly changing the memory of the image.
      pixel.s = 0;
    }
  }

  return image;
}



/**
 * Returns an image with a spotlight centered at (`centerX`, `centerY`).
 *
 * A spotlight adjusts the luminance of a pixel based on the distance the pixel
 * is away from the center by decreasing the luminance by 0.5% per 1 pixel euclidean
 * distance away from the center.
 *
 * For example, a pixel 3 pixels above and 4 pixels to the right of the center
 * is a total of `sqrt((3 * 3) + (4 * 4)) = sqrt(25) = 5` pixels away and
 * its luminance is decreased by 2.5% (0.975x its original value).  At a
 * distance over 160 pixels away, the luminance will always decreased by 80%.
 * 
 * The modified PNG is then returned.
 *
 * @param image A PNG object which holds the image data to be modified.
 * @param centerX The center x coordinate of the crosshair which is to be drawn.
 * @param centerY The center y coordinate of the crosshair which is to be drawn.
 *
 * @return The image with a spotlight.
 */
PNG createSpotlight(PNG image, int centerX, int centerY) {

  for (unsigned x = 0; x < image.width(); x++) {
    for (unsigned y = 0; y < image.height(); y++) {

      HSLAPixel & pixel = image.getPixel(x, y);

      //calculate the distance from current pixel to the center
      int dist_x = labs(x - centerX);
      int dist_y = labs(y - centerY);
      double dist = sqrt(pow(dist_x,2) + pow(dist_y,2));

      if (dist > 160){
	pixel.l = pixel.l * 0.2;
      }
      else{
        pixel.l = pixel.l * (1 - (0.005 * dist));
      }
    }
  }
  return image;

}


/**
 * Returns a image transformed to Illini colors.
 *
 * The hue of every pixel is set to the a hue value of either orange or
 * blue, based on if the pixel's hue value is closer to orange than blue.
 *
 * @param image A PNG object which holds the image data to be modified.
 *
 * @return The illinify'd image.
**/
PNG illinify(PNG image) {

  for (unsigned x = 0; x < image.width(); x++) {
    for (unsigned y = 0; y < image.height(); y++) {

      HSLAPixel & pixel = image.getPixel(x, y);

      unsigned dist_11 = 0;
      unsigned dist_216 = 0;

      if(pixel.h>11 && pixel.h<216){ //h between 11 and 216
         dist_11 = pixel.h - 11;
	 dist_216 = 216 - pixel.h;
      }
      else if(pixel.h>=216){ //h wraps around after 360 so we use 360+11=371
	dist_11 = 371 - pixel.h;
	dist_216 = pixel.h - 216;
      }
      else if(pixel.h >= 0 && pixel.h <= 11){  //last section (0~11) should also be covered
         pixel.h = 11;
      }

      if(dist_11>dist_216){
        pixel.h = 216;
      }
      else{
	pixel.h = 11;
      }
    }
  }
  return image;
}


/**
* Returns an immge that has been watermarked by another image.
*
* The luminance of every pixel of the second image is checked, if that
* pixel's luminance is 1 (100%), then the pixel at the same location on
* the first image has its luminance increased by 0.2.
*
* @param firstImage  The first of the two PNGs, which is the base image.
* @param secondImage The second of the two PNGs, which acts as the stencil.
*
* @return The watermarked image.
*/
PNG watermark(PNG firstImage, PNG secondImage) {

  // only care about the overlapped area
  unsigned x1 = firstImage.width();
  unsigned x2 = secondImage.width();
  unsigned y1 = firstImage.height();
  unsigned y2 = secondImage.height();
  unsigned width_out = std::min(x1, x2);
  unsigned height_out = std::min(y1, y2);

  for(unsigned x = 0; x < width_out; x++){
    for(unsigned y = 0; y < height_out; y++){
	HSLAPixel & pixel1 = firstImage.getPixel(x, y);
	HSLAPixel & pixel2 = secondImage.getPixel(x,y);
	if(pixel2.l == 1){
	  pixel1.l = pixel1.l + 0.2;
	}
    }
  }
  return firstImage;
}

#include "tictactoe.hpp"

// using namespace eosio should really be here rather than in the header

void tictactoe::create(const name &challenger, name &host) {
    require_auth(host);
    check(challenger != host, "Challenger should not be the same as the host.");

    // Check if game already exists
    games existingHostGames(get_self(), host.value);
    auto itr = existingHostGames.find(challenger.value);
    check(itr == existingHostGames.end(), "Game already exists.");

    existingHostGames.emplace(host, [&](auto &g) {
        g.challenger = challenger;
        g.host = host;
        g.turn = host;
    });
}

void tictactoe::restart(const name &challenger, const name &host, const name &by)
{
    check(has_auth(by), "Only " + by.to_string() + "can restart the game.");

    // Check if game exists
    games existingHostGames(get_self(), host.value);
    auto itr = existingHostGames.find(challenger.value);
    check(itr != existingHostGames.end(), "Game does not exist.");

    // Check if this game belongs to the action sender
    check(by == itr->host || by == itr->challenger, "This is not your game.");

    // Reset game
    existingHostGames.modify(itr, itr->host, [](auto &g) {
        g.resetGame();
    });
}

void tictactoe::close(const name &challenger, const name &host)
{
    check(has_auth(host), "Only the host can close the game.");

    require_auth(host);

    // Check if game exists
    games existingHostGames(get_self(), host.value);
    auto itr = existingHostGames.find(challenger.value);
    check(itr != existingHostGames.end(), "Game does not exist.");

    // Remove game
    existingHostGames.erase(itr);
}

bool tictactoe::isEmptyCell(const uint8_t &cell)
{
    return cell == 0;
}

bool tictactoe::isValidMove(const uint16_t &row, const uint16_t &column, const std::vector<uint8_t> &board)
{
    uint32_t movementLocation = row * game::boardWidth + column;
    bool isValid = movementLocation < board.size() && isEmptyCell(board[movementLocation]);
    return isValid;
}

name tictactoe::getWinner(const game &currentGame)
{
    auto &board = currentGame.board;

    bool isBoardFull = true;

    // Use bitwise AND operator to determine the consecutive values of each column, row and diagonal
    // Since 3 == 0b11, 2 == 0b10, 1 = 0b01, 0 = 0b00
    std::vector<uint32_t> consecutiveColumn(game::boardWidth, 3);
    std::vector<uint32_t> consecutiveRow(game::boardHeight, 3);
    uint32_t consecutiveDiagonalBackslash = 3;
    uint32_t consecutiveDiagonalSlash = 3;

    for (uint32_t i = 0; i < board.size(); i++)
    {
        isBoardFull &= isEmptyCell(board[i]);
        uint16_t row = uint16_t(i / game::boardWidth);
        uint16_t column = uint16_t(i % game::boardWidth);

        // Calculate consecutive row and column value
        consecutiveRow[column] = consecutiveRow[column] & board[i];
        consecutiveColumn[row] = consecutiveColumn[row] & board[i];
        // Calculate consecutive diagonal \ value
        if (row == column)
        {
            consecutiveDiagonalBackslash = consecutiveDiagonalBackslash & board[i];
        }
        // Calculate consecutive diagonal / value
        if (row + column == game::boardWidth - 1)
        {
            consecutiveDiagonalSlash = consecutiveDiagonalSlash & board[i];
        }
    }

    // Inspect the value of all consecutive row, column, and diagonal and determine winner
    std::vector<uint32_t> aggregate = {consecutiveDiagonalBackslash, consecutiveDiagonalSlash};
    aggregate.insert(aggregate.end(), consecutiveColumn.begin(), consecutiveColumn.end());
    aggregate.insert(aggregate.end(), consecutiveRow.begin(), consecutiveRow.end());

    for (auto value : aggregate)
    {
        if (value == 1)
        {
            return currentGame.host;
        }
        else if (value == 2)
        {
            return currentGame.challenger;
        }
    }
    // Draw if the board is full, otherwise the winner is not determined yet
    return isBoardFull ? draw : none;
}

void tictactoe::move(const name &challenger, const name &host, const name &by, const uint16_t &row, const uint16_t &column)
{
    check(has_auth(by), "The next move should be made by " + by.to_string());

    // Check if game exists
    games existingHostGames(get_self(), host.value);
    auto itr = existingHostGames.find(challenger.value);
    check(itr != existingHostGames.end(), "Game does not exist.");

    // Check if this game hasn't ended yet
    check(itr->winner == none, "The game has ended.");

    // Check if this game belongs to the action sender
    check(by == itr->host || by == itr->challenger, "This is not your game.");
    // Check if this is the  action sender's turn
    check(by == itr->turn, "it's not your turn yet!");

    // Check if user makes a valid movement
    check(isValidMove(row, column, itr->board), "Not a valid movement.");

    // Fill the cell, 1 for host, 2 for challenger
    //TODO could use constant for 1 and 2 as well
    const uint8_t cellValue = itr->turn == itr->host ? 1 : 2;
    const auto turn = itr->turn == itr->host ? itr->challenger : itr->host;
    existingHostGames.modify(itr, itr->host, [&](auto &g) {
        g.board[row * game::boardWidth + column] = cellValue;
        g.turn = turn;
        g.winner = getWinner(g);
    });
}

#include <bits/stdc++.h>
using namespace std;

#define SIZE 10

class TicketSystem{
    public:
    int front, rear;
    int *tickets;

    TicketSystem(){
        tickets = new int[SIZE];
        front = rear = -1;
    }

    bool isFull(){
        return rear == SIZE-1;
    }

    bool isEmpty(){
        return front == -1 || front > rear;
    }

    void enqueue(int ID){
        if(isFull()){
            cout << "Queue is full" << endl;
            return;
        }

        if(isEmpty())
            front = 0;

        tickets[++rear] = ID;
    }

    void dequeue(){
        if(isEmpty()){
            cout << "Queue is empty" << endl;
            return;
        }

        front++;
    }

    void display(){
        if(isEmpty()){
            cout << "Queue is empty" << endl;
            return;
        }

        cout << "Tickets are: \n";
        for(int i = 0; i < SIZE; i++){
            cout << "\t" << tickets[i] << endl;
        }
        cout << endl;
    }

};

// THE MAIN IS Crafted with routine coding tools
int main(){
    TicketSystem ts;

    // Add 10 passengers
    for (int i = 1; i <= 10; i++) {
        ts.enqueue(i);
    }

    ts.display();

    // Remove 5 passengers
    for (int i = 0; i < 5; i++) {
        ts.dequeue();
    }

    ts.display();

    // Attempt to add 5 more passengers
    for (int i = 11; i <= 15; i++) {
        ts.enqueue(i);
    }

    ts.display();

    return 0;
}

#include "analysis_context.hpp"
#include "arithmetic_operations.hpp"
#include <vtil/amd64>

namespace vmpattack
{
    // Processes the instruction, updating any properties that the instruction
    // may change.
    //
    void analysis_context::process( const instruction* instruction )
    {
        // If the expression is valid, attempt to record the current instruction
        // in the expression
        //
        if ( expression )
        {
            // Try to get operation descriptor for the current instruction
            //
            if ( auto operation_desc = operation_desc_from_instruction( instruction ) )
            {
                uint8_t read_count = 0, write_count = 0;
                cs_regs read_regs, write_regs;

                // Fetch registers read/written to by instruction
                //
                cs_regs_access( disassembler::get().get_handle(), &instruction->ins, read_regs, &read_count, write_regs, &write_count );

                // Flip flag if expression target register is being written to
                //
                bool writes_to_reg = false;
                for ( int i = 0; i < write_count; i++ )
                {
                    if ( register_base_equal( ( x86_reg )write_regs[ i ], expression_register ) )
                    {
                        writes_to_reg = true;
                        break;
                    }
                }

                // If it does write to the register, add it to the expression
                //
                if ( writes_to_reg )
                {
                    if ( auto operation = arithmetic_operation::from_instruction( instruction ) )
                        expression->operations.push_back( *operation );

                }
            }
        }

        // If we are currently tracking any registers (ie. tracked register is not empty) attempt
        // to update them using the current instruction.
        //
        if ( tracked_registers.size() > 0
          && ( instruction->ins.id == X86_INS_MOV
          || instruction->ins.id == X86_INS_XCHG ) )
        {
            // If both operands are registers.
            //
            if ( instruction->operand( 0 ).type == X86_OP_REG
              && instruction->operand( 1 ).type == X86_OP_REG )
            {
                // Loop through tracked registers vector.
                //
                for ( x86_reg* tracked_reg : tracked_registers )
                {
                    if ( instruction->ins.id == X86_INS_MOV )
                    {
                        // operand( 0 ) = operand( 1 )
                        //
                        if ( instruction->operand( 1 ).reg == *tracked_reg )
                            *tracked_reg = instruction->operand( 0 ).reg;
                    }
                    else if ( instruction->ins.id == X86_INS_XCHG )
                    {
                        // operand ( 0 ) = operand( 1 ) && operand( 1 ) = operand( 0 )
                        //
                        if ( instruction->operand( 0 ).reg == *tracked_reg )
                            *tracked_reg = instruction->operand( 1 ).reg;
                        else if ( instruction->operand( 1 ).reg == *tracked_reg )
                            *tracked_reg = instruction->operand( 0 ).reg;
                    }
                }
            }
        }

        // If we are currently tracking stack pushes, update them.
        //
        if ( pushed_registers )
        {
            if ( instruction->ins.id == X86_INS_PUSH
              && instruction->operand( 0 ).type == X86_OP_REG )
                pushed_registers->push_back( instruction->operand( 0 ).reg );
            else if ( instruction->ins.id == X86_INS_PUSHFQ
                   || instruction->ins.id == X86_INS_PUSHFD
                   || instruction->ins.id == X86_INS_PUSHF )
                pushed_registers->push_back( X86_REG_EFLAGS );
        }

        // If we are currently tracking stack pops, update them.
        //
        if ( popped_registers )
        {
            if ( instruction->ins.id == X86_INS_POP
                 && instruction->operand( 0 ).type == X86_OP_REG )
                popped_registers->push_back( instruction->operand( 0 ).reg );
            else if ( instruction->ins.id == X86_INS_POPFQ
                      || instruction->ins.id == X86_INS_POPFD
                      || instruction->ins.id == X86_INS_POPF )
                popped_registers->push_back( X86_REG_EFLAGS );
        }
    }
}

// aho_corasick.cpp
// Eric K. Zhang; July 15, 2016

// Problem: Given a text string and a dictionary
// of search strings, find all occurences of a search
// string in the text (overlap included).

// Bad solution: Run KMP a lot, giving O(N * |S|)

// Good solution: Aho-Corasick gives O(N + sum|S|) by
// essentially extending KMP, creating a trie with
// "failure" functions. Basically a FSM.

// Note: The automation generated by Aho-Corasick can
// also be used as a first step in many problems. This
// is often how it'll be used (e.g. sparse table) in
// competitions, since Rabin-Karp is easier to code
// for the simple version of the problem.

#include <bits/stdc++.h>
using namespace std;

typedef long long LL;

#define MAXN 100013
int N; // size of dictionary
string dict[MAXN];
string text;

#define MAXM 100013
int M; // number of states in the automation
int g[MAXM][26]; // the normal edges in the trie
int f[MAXM]; // failure function
LL out[MAXM]; // output function

int aho_corasick() {
	memset(g, -1, sizeof g);
	memset(out, 0, sizeof out);

	int nodes = 1;

	// build the trie
	for (int i = 0; i < N; i++) {
		string& s = dict[i];
		int cur = 0;

		for (int j = 0; j < s.size(); j++) {
			if (g[cur][s[j] - 'a'] == -1) {
				g[cur][s[j] - 'a'] = nodes++;
			}
			cur = g[cur][s[j] - 'a'];
		}
		out[cur]++;
	}

	for (int ch = 0; ch < 26; ch++) {
		if (g[0][ch] == -1) {
			g[0][ch] = 0;
		}
	}

	// BFS to calculate out and failure functions
	memset(f, -1, sizeof f);
	queue<int> q;
	for (int ch = 0; ch < 26; ch++) {
		if (g[0][ch] != 0) {
			f[g[0][ch]] = 0;
			q.push(g[0][ch]);
		}
	}

	while (!q.empty()) {
		int state = q.front();
		q.pop();

		for (int ch = 0; ch < 26; ch++) {
			if (g[state][ch] == -1) continue;

			int fail = f[state];
			while (g[fail][ch] == -1) {
				fail = f[fail];
			}

			f[g[state][ch]] = g[fail][ch];
			out[g[state][ch]] += out[g[fail][ch]];

			q.push(g[state][ch]);
		}
	}

	return nodes;
}

LL search() {
	// Using the Aho-Corasick automation, search the text.
	int state = 0;
	LL ret = 0;
	for (char c : text) {
		while (g[state][c - 'a'] == -1) {
			state = f[state];
		}
		state = g[state][c - 'a'];
		ret += out[state];
	}
	// It's that simple!
	return ret;
}

int main() {
	// make I/O faster
	ios_base::sync_with_stdio(false);
	cin.tie(0);

	freopen("aho_corasick.in", "r", stdin);

	cin >> N;
	for (int i = 0; i < N; i++) {
		cin >> dict[i];
	}
	cin >> text;

	M = aho_corasick();
	LL result = search();

	cout << result << endl;
	return 0;
}

