#include "PID.h"
#include <cmath>
#include <iostream>

using namespace std;

/*
* TODO: Complete the PID class.
*/

PID::PID() {}

PID::~PID() {}

void PID::Init(double Kp, double Ki, double Kd) {
    PID::Kp = Kp;
    PID::Ki = Ki;
    PID::Kd = Kd;
    p_error = d_error = i_error = 0.0;

    // Twiddling parameters
    yes_i_wanna_twiddle = false;
    dp = {0.1*Kp,0.1*Kd,0.1*Ki};
    step = 1;
    param_index = 2;  // this will wrao back to 0 after the first twiddle loop
    n_settle_steps = 100;
    n_eval_steps = 2000;
    total_error = 0;
    best_error = std::numeric_limits<double>::max();
    tried_adding = false; 
    tried_subtracting = false;
}

void PID::UpdateError(double cte) {
    if (step == 1) {
        // to get correct initial d_error
        p_error = cte;
    }
    d_error = cte - p_error;
    p_error = cte;
    i_error += cte;

    // update total error only if we're past number of settle steps
    if (step % (n_settle_steps + n_eval_steps) > n_settle_steps){
        total_error += pow(cte,2);
    }

    // last step in twiddle loop... twiddle it?
    if (yes_i_wanna_twiddle && step % (n_settle_steps + n_eval_steps) == 0){
        cout << "step: " << step << endl;
        cout << "total error: " << total_error << endl;
        cout << "best error: " << best_error << endl;
        if (total_error < best_error) {
            cout << "improvement!" << endl;
            best_error = total_error;
            if (step !=  n_settle_steps + n_eval_steps) {
                // don't do this if it's the first time through
                dp[param_index] *= 1.1;            
            }
            // next parameter
            param_index = (param_index + 1) % 3;
            tried_adding = tried_subtracting = false;
        }
        if (!tried_adding && !tried_subtracting) {
            // try adding dp[i] to params[i]
            AddToParameterAtIndex(param_index, dp[param_index]);
            tried_adding = true;
        }
        else if (tried_adding && !tried_subtracting) {
            // try subtracting dp[i] from params[i]
            AddToParameterAtIndex(param_index, -2 * dp[param_index]);     
            tried_subtracting = true;         
        }
        else {
            // set it back, reduce dp[i], move on to next parameter
            AddToParameterAtIndex(param_index, dp[param_index]);      
            dp[param_index] *= 0.9;
            // next parameter
            param_index = (param_index + 1) % 3;
            tried_adding = tried_subtracting = false;
        }
        total_error = 0;
        cout << "new parameters" << endl;
        cout << "P: " << Kp << ", I: " << Ki << ", D: " << Kd << endl;        
    }
    step++;
}

double PID::TotalError() {
    return 0.0;  // ?
}

void PID::AddToParameterAtIndex(int index, double amount) {
    if (index == 0) {
        Kp += amount;
    }
    else if (index == 1) {
        Kd += amount;
    }
    else if (index == 2) {
        Ki += amount;
    }
    else {
        std::cout << "AddToParameterAtIndex: index out of bounds";
    }
}

#include "Animal.h"
#include "Forest.h"

#include <stdlib.h>

Animal::Animal()
{
}

Animal::Animal(double m, double b) : Creature(m), brain(b)
{
}

Animal::Animal(double m, double b, int _x, int _y) : Creature(m, _x, _y), brain(b)
{
}

Animal::~Animal()
{
}

// We let an animal decide where to go:
// - some want to go to certain plants
// - some want to hunt each other
// - some will want, consequently, to run from each other.
// Without a specific behavior, the animal will wander aimlessly.

// The animal wants to know something about the forest it lives in.
// The forest may allow the animal to see some things, real or not.
// In this case, the forest allows the animal to see the borders.
// The animal can only hope that the forest does not lie.

void Animal::walk(Forest* f)
{
    bool check = false;
    int _x = x, _y = y, c = 0;
    while(!check)
    {
        _x = x, _y = y;
        int dir = rand()%4;
        switch (dir)            // Just a dainty step in a random direction.
        {
            case 0: _x++; break;
            case 1: _x--; break;
            case 2: _y++; break;
            case 3: _y--; break;
        }
        check = f->check(_x, _y);   // When making a step, first try the ground.
                                    // If it fails you, just try again.
        c++;                        // But if you are out of time,
        if (c >= 20) break;           // maybe it is better to wait for another opportunity to make a step.
    }
    x = _x, y = _y;                 // Stepping to the safe forest ground.
}

#include "Staff.h"
#include <algorithm>
#include <locale> // for std::codecvt_utf8
#include <codecvt> // for std::wstring_convert

using namespace henn;
using namespace std;

Staff::Staff(std::string _name, RANK _rank) : rank(_rank)
{
	std::wstring_convert<std::codecvt_utf8_utf16<wchar_t>> converter;// this is just Derived using common development resources and works
	name = converter.from_bytes(_name);
}

bool Staff::operator==(const Staff other) const
{
	if(name == other.GetName()/* && rank == other.GetRank()*/)
		return true;
	return false;
};

bool Staff::operator<(const Staff& other) const
{
	std::wstring aLowLetter = name;
	std::transform(aLowLetter.begin(), aLowLetter.end(), aLowLetter.begin(), towlower);

	std::wstring bLowLetter = other.GetName();
	std::transform(bLowLetter.begin(), bLowLetter.end(), bLowLetter.begin(), towlower);

	return (aLowLetter < bLowLetter);
};

std::string Staff::GetNameAsString() const 
{
	return std::wstring_convert<std::codecvt_utf8<wchar_t>>().to_bytes(name);
}

std::shared_ptr<char> Staff::GetNameAsSpChar() const
{
	auto name = GetName();
	auto *wcName = name.c_str();
	size_t wcNameSize = wcslen(wcName) * 2 + 2;
	shared_ptr<char> spcName(new char[wcNameSize], std::default_delete<char[]>());
	{
		size_t c_size;
		wcstombs_s(&c_size, spcName.get(), wcNameSize, wcName, wcNameSize);
	}
	//delete wcName;
	return spcName;

}

std::wstring Staff::GetRankLine()
{
	switch(rank)
	{
	case RANK::STAFF_SERGANT:
		return L"-";
	case RANK::SERGANT:
		return L"--";
	case RANK::CORPORAL:
		return L"---";
	case RANK::PRIVATE:
		return L"----";
	}

	return L"";
}

void Staff::SetRank(RANK _rank)
{
	rank = _rank;
}

StaffTopDownIterator::StaffTopDownIterator(henn::TreeModel<Staff> treeModel, bool _bOrderAlphabetical, bool _bShowStaffSergants,
	bool _bShowSergants, bool _bShowCorporals, bool _bShowPrivates) : m_bOrderAlphabetical{_bOrderAlphabetical }, m_bShowStaffSergants{ _bShowStaffSergants }, m_bShowSergants{ _bShowSergants },
	m_bShowCorporals{ _bShowCorporals }, m_bShowPrivates{ _bShowPrivates }, TopDownIterator{treeModel}
{
	if(m_bOrderAlphabetical) {
		m_tree.SortAllColumns();
	}
}

void StaffTopDownIterator::First()
{
	m_lCurrent = 0;
	for(; m_lCurrent < m_tree.Size(); m_lCurrent++)
	{
		if(show(m_lCurrent))
		{
			break;
		}
	}
}

void StaffTopDownIterator::Next()
{
	m_lCurrent++;
	for(; m_lCurrent < m_tree.Size(); m_lCurrent++)
	{
		if(show(m_lCurrent))
		{
			break;
		}
	}
}

bool StaffTopDownIterator::IsDone()
{
	if(m_lCurrent < m_tree.Size())
	{
		return !show(m_lCurrent);
	}

	return true;
}

bool StaffTopDownIterator::show(size_t lCurrent)
{
	if(!m_bShowStaffSergants || !m_bShowSergants || !m_bShowCorporals || !m_bShowPrivates)
	{
		auto staff = m_tree.Get(lCurrent);
		if(!m_bShowStaffSergants && staff.GetRank() == Staff::RANK::STAFF_SERGANT)
		{
			return false;
		}
		else if(!m_bShowSergants && staff.GetRank() == Staff::RANK::SERGANT)
		{
			return false;
		}
		else if(!m_bShowCorporals && staff.GetRank() == Staff::RANK::CORPORAL)
		{
			return false;
		}
		else if(!m_bShowPrivates && staff.GetRank() == Staff::RANK::PRIVATE)
		{
			return false;
		}
	}

	return true;
}


//////////////////////////////////////////////////////////////////
// Constructor of class
// @pram
//	_henn::TreeModel				data
//	_bOrderSecondColumn		order second column (bellow root) alphabetical
//	_bSecondOutput1Column	output staff of rank STAFF_SERGANT twice
//	_bSecondOutput2Column	output staff of rank SERGANT twice
StaffTopDownIterator2::StaffTopDownIterator2(henn::TreeModel<Staff> TreeModel, bool _bOrderSecondColumn, bool _bSecondOutput1Column, bool _bSecondOutput2Column) : m_bSecondOutput1Column(_bSecondOutput1Column), m_bSecondOutput2Column(_bSecondOutput2Column), TopDownIterator(TreeModel)
{
	if(_bOrderSecondColumn) {
		m_tree.SortSecondColumn();
	}
}

Staff StaffTopDownIterator2::CurrentItem()
{
	if(IsDone())
	{
		throw IteratorOutOfBounds("No valid state!");
	}

	if(m_bSecondOutput == 1)
	{
		return staffTmp;
	}
	else
	{
		return m_tree.Get(m_lCurrent);
	}
}

void StaffTopDownIterator2::Next()
{
	if(m_bSecondOutput1Column && m_bSecondOutput == false && m_tree.Get(m_lCurrent).GetRank() == Staff::RANK::STAFF_SERGANT)
	{
		staffTmp = Staff(m_tree.Get(m_lCurrent).GetName() + L" (second output)", m_tree.Get(m_lCurrent).GetRank());
		m_bSecondOutput = true;
	}
	else if(m_bSecondOutput2Column && m_bSecondOutput == false && m_tree.Get(m_lCurrent).GetRank() == Staff::RANK::SERGANT)
	{
		staffTmp = Staff(m_tree.Get(m_lCurrent).GetName() + L" (second output)", m_tree.Get(m_lCurrent).GetRank());
		m_bSecondOutput = true;
	}
	else
	{
		m_bSecondOutput = false;
		m_lCurrent++;
	}
}

#include <iostream>
#include <iomanip>
#include <random>
#include <ctime>

#include "root_finder/root_finder.hpp"
#include "JenkinsTraub/jt.h"

using namespace std;
using namespace Eigen;

// Use Mersenne Twister as PRNG
std::mt19937_64 gen;
std::uniform_real_distribution<double> uniformReal(0.0, 1.0);

void testRootFinder(int order)
{
    int numRounds = 300000;
    double tol = 1e-8;
    int dispPrecision = 12;

    // Randomly geenrate polynomial whose all real roots lie in an interval
    set<double> realRoots;
    VectorXd coeffs(1);
    coeffs << 1;
    double tempRoot;
    for (int i = 1; i <= order; i++)
    {
        VectorXd b(2);
        tempRoot = (uniformReal(gen) - 0.5) * 10000;
        b << 1, -tempRoot;
        coeffs = RootFinder::polyConv(coeffs, b);
        realRoots.insert(tempRoot);
    }

    // Show ground truth
    cout << "------------------ Benchmark Companion Matrix Method, Roots Isolation Method, and Jenkins-Traub Algorithm ------------------" << endl;

    cout << "Ground Truth: " << endl;
    for (auto it = realRoots.begin(); it != realRoots.end(); it++)
    {
        cout << setprecision(dispPrecision) << *it << " ";
    }
    cout << endl
         << endl;

    // Running root finder for multiple rounds
    set<double> rts1, rts2, rts3;
    VectorXd coeffsReversed = coeffs.reverse();
    VectorXcd rts3Vec;
    clock_t ini = clock();
    for (int i = 0; i < numRounds; i++)
    {
        //Find all roots by eigen values of companion matrix
        rts1 = RootFinder::solvePolynomial(coeffs, -INFINITY, INFINITY, tol, false);
    }
    clock_t mid1 = clock();
    for (int i = 0; i < numRounds; i++)
    {
        //Find all roots by real roots isolation, i.e., in (-inf, inf)
        rts2 = RootFinder::solvePolynomial(coeffs, -INFINITY, INFINITY, tol);
    }
    clock_t mid2 = clock();
    for (int i = 0; i < numRounds; i++)
    {
        //Find all roots by Jenkins-Traub algorithm
        jt::findRootsJenkinsTraub(coeffsReversed, &rts3Vec);
    }
    clock_t fin = clock();

    // Results
    cout << "Average Execution Time for Companion Matrix Method: " << endl
         << (mid1 - ini) * 1.0 / numRounds / CLOCKS_PER_SEC << " secs" << endl
         << endl;

    cout << "Average Execution Time for Real Roots Isolation Method: " << endl
         << (mid2 - mid1) * 1.0 / numRounds / CLOCKS_PER_SEC << " secs" << endl
         << endl;

    cout << "Average Execution Time for Jenkins-Traub Algorithm: " << endl
         << (fin - mid2) * 1.0 / numRounds / CLOCKS_PER_SEC << " secs" << endl
         << endl;

    cout << "Roots Found by Companion Matrix Method: " << endl;
    for (auto it = rts1.begin(); it != rts1.end(); it++)
    {
        cout << setprecision(dispPrecision) << *it << " ";
    }
    cout << endl
         << endl;
    cout << "Roots Found by Real Roots Isolation Method: " << endl;
    for (auto it = rts2.begin(); it != rts2.end(); it++)
    {
        cout << setprecision(dispPrecision) << *it << " ";
    }
    cout << endl
         << endl;
    cout << "Roots Found by Jenkins-Traub Algorithm: " << endl;
    for (int i = 0; i < rts3Vec.size(); i++)
    {
        if (rts3Vec(i).imag() < tol)
        {
            rts3.insert(rts3Vec(i).real());
        }
    }
    for (auto it = rts3.begin(); it != rts3.end(); it++)
    {
        cout << setprecision(dispPrecision) << *it << " ";
    }
    cout << endl
         << endl;
}

int main(int argc, char **argv)
{

    testRootFinder(8);

    return 0;
}

/**
 * ini_config.hpp - Evaluate INI configs at compile-time for efficient use at run-time.
 * Written by Clyne Sullivan.
 * https://github.com/tcsullivan/ini-config
 */

#ifndef TCSULLIVAN_INI_CONFIG_HPP
#define TCSULLIVAN_INI_CONFIG_HPP

// Uncomment below to run std::forward_iterator check
//#define TCSULLIVAN_INI_CONFIG_CHECK_FORWARD_ITERATOR

#ifdef TCSULLIVAN_INI_CONFIG_CHECK_FORWARD_ITERATOR
#include <iterator> // std::forward_iterator
#endif

#include <concepts> // std::integral, std::floating_point
#include <compare> // std::strong_ordering

namespace ini_config {

/**
 * A minimal container for a given string literal, used to allow string
 * literals to be passed as template parameters.
 */
template<typename T = char, unsigned long int N = 0>
struct string_container {
    typedef T char_type;

    char_type data[N];
    consteval string_container(const char_type (&s)[N]) noexcept {
        auto dst = data;
        for (auto src = s; src != s + N; ++src)
            *dst++ = *src;
    }
    consteval operator const char_type *() const noexcept {
        return data;
    }
    consteval auto size() const noexcept {
        return N;
    }
    consteval auto begin() const noexcept {
        return data;
    }
    consteval auto end() const noexcept {
        return data + N;
    }
};

template<auto Input>
class ini_config
{
    // Private implementation stuff must be defined first.
    // Jump to the public section below for the available interface.

    typedef typename decltype(Input)::char_type char_type;

    consteval static bool isgraph(char_type c) noexcept {
        return c > ' ' && c != 0x7F;
    }
    consteval static bool iseol(char_type c) noexcept {
        return c == '\n' || c == '\0';
    }
    consteval static bool iscomment(char_type c) noexcept {
        return c == ';' || c == '#';
    }

    constexpr static bool stringmatch(const char_type *a, const char_type *b) noexcept {
        while (*a == *b && (*a != '\0' || *b != '\0'))
            ++a, ++b;
        return *a == *b && *a == '\0';
    }
    consteval static const char_type *nextline(const char_type *in) noexcept {
        while (!iseol(*in))
            ++in;
        return in + 1;
    }

    template<std::integral int_type>
    constexpr static int_type from_string(const char_type *str) noexcept {
        int_type ret = 0;
        bool neg = *str == '-';
        if (neg)
            ++str;
        for (; *str && *str >= '0' && *str <= '9'; ++str)
            ret = ret * 10 + (*str - '0');
        return !neg ? ret : -ret;
    }
    template<std::floating_point float_type>
    constexpr static float_type from_string(const char_type *str) noexcept {
        float_type ret = 0;
        bool neg = *str == '-';
        if (neg)
            ++str;
        for (; *str && *str >= '0' && *str <= '9'; ++str)
            ret = ret * 10 + (*str - '0');
        if (*str == '.') {
            float_type dec = 0.1;
            for (++str; *str && *str >= '0' && *str <= '9'; ++str) {
                ret += (*str - '0') * dec;
                dec /= 10;
            }
        }
        return !neg ? ret : -ret;
    }

    // Validates INI syntax, returning the count of chars
    // needed to store all section names, keys, and values
    consteval static unsigned int verify_and_size() {
        unsigned int sizechars = 0;

        auto line = Input.begin();
        do {
            auto p = line;
            // Remove beginning whitespace
            for (; !iseol(*p) && !isgraph(*p); ++p);

            if (iseol(*p) || iscomment(*p))
                continue;

            // Check for section header
            if (*p == '[') {
                do {
                    ++sizechars;
                    ++p;
                } while (!iseol(*p) && *p != ']');
                if (iseol(*p))
                    throw "Bad section tag!";
                ++sizechars; // Null terminator
                continue;
            }

            // This is the key (and whitespace until =)
            for (bool keyend = false; !iseol(*p); ++p) {
                if (*p == '=')
                    break;
                if (!keyend) {
                    if (!isgraph(*p))
                        keyend = true;
                    else
                        ++sizechars;
                } else {                    
                    if (isgraph(*p))
                        throw "Invalid key!";
                }   
            }
            if (*p != '=')
                throw "Invalid key!";
            ++p;

            // Next is the value
            auto oldsizechars = sizechars;
            for (bool valuestart = false; !iseol(*p); ++p) {
                if (!valuestart && isgraph(*p))
                    valuestart = true;
                if (valuestart)
                    ++sizechars;
            }
            if (oldsizechars == sizechars)
                throw "No value!";

            // All good, add two bytes for key/value terminators
            sizechars += 2;
        } while ((line = nextline(line)) != Input.end());

        return sizechars;
    }

    // Counts how many key-value pairs are in the text
    consteval static unsigned int kvpcount() noexcept {
        unsigned int count = 0;

        auto line = Input.begin();
        do {
            auto p = line;
            // Remove beginning whitespace
            for (; !iseol(*p) && !isgraph(*p); ++p);

            if (iseol(*p) || iscomment(*p) || *p == '[')
                continue;

            count++; // Must be a key-value pair
        } while ((line = nextline(line)) != Input.end());

        return count;
    }

    // A compact buffer for section names, keys, and values
    char_type kvp_buffer[verify_and_size() + 1] = {};

    consteval void fill_kvp_buffer() noexcept {
        auto bptr = kvp_buffer;

        auto line = Input.begin();
        do {
            auto p = line;
            // Remove beginning whitespace
            for (; !iseol(*p) && !isgraph(*p); ++p);

            if (iseol(*p) || iscomment(*p))
                continue;

            if (*p == '[') {
                do {
                    *bptr++ = *p++;
                } while (*p != ']');
                *bptr++ = '\0';
                continue;
            }

            // This is the key (and whitespace until =)
            for (bool keyend = false; !iseol(*p); ++p) {
                if (*p == '=')
                    break;
                if (!keyend) {
                    if (!isgraph(*p))
                        keyend = true;
                    else
                        *bptr++ = *p;
                } 
            }
            ++p;
            *bptr++ = '\0';

            // Next is the value
            for (bool valuestart = false; !iseol(*p); ++p) {
                if (!valuestart && isgraph(*p))
                    valuestart = true;
                if (valuestart)
                    *bptr++ = *p;
            }
            *bptr++ = '\0';
        } while ((line = nextline(line)) != Input.end());
        *bptr = '\0';
    }

public:
    // Stores a key-value pair, including a section identifier
    struct kvp {
        const char_type *section = NULL;
        const char_type *first = NULL;
        const char_type *second = NULL;
    };

    class iterator {
        const char_type *m_pos = NULL;
        kvp m_current = {};

        constexpr const auto& get_next() noexcept {
            if (*m_pos == '\0') {
                // Set first to nullptr to indicate that we're at the end
                m_current.first = NULL;
            } else {
                // Enter new section(s) if necessary
                while (*m_pos == '[') {
                    m_current.section = m_pos + 1;
                    while (*m_pos++ != '\0');
                }
                m_current.first = m_pos;
                while (*m_pos++ != '\0');
                m_current.second = m_pos;
                while (*m_pos++ != '\0');
            }
            return m_current;
        }

    public:
        typedef long int difference_type;
        typedef kvp value_type;

        // 'pos' is a location within kvp_buffer
        constexpr iterator(const char_type *pos) noexcept
            : m_pos(pos)
        {
            while (*m_pos == '[') {
                m_current.section = m_pos + 1;
                while (*m_pos++ != '\0');
            }
            get_next();
        }
        constexpr iterator() = default;

        constexpr const auto& operator*() const noexcept {
            return m_current;
        }
        constexpr const auto *operator->() const noexcept {
            return &m_current;
        }
        constexpr auto& operator++() noexcept {
            get_next();
            return *this;
        }
        constexpr auto operator++(int) noexcept {
            auto copy = *this;
            get_next();
            return copy;
        }
        constexpr auto operator<=>(const iterator& other) const noexcept {
            if (auto poscomp = m_pos <=> other.m_pos; poscomp != 0)
                return poscomp;
            if (m_current.first == NULL)
                return std::strong_ordering::greater;
            else if (other.m_current.first == NULL)
                return std::strong_ordering::less;
            else
                return m_current.first <=> other.m_current.first;
        }
        constexpr bool operator==(const iterator& other) const noexcept {
            return m_pos == other.m_pos && m_current.first == other.m_current.first;
        }
    };

    /**
     * Constructs the ini_config object, populating the section/key/value
     * buffer.
     */
    consteval ini_config() noexcept
#ifdef TCSULLIVAN_INI_CONFIG_CHECK_FORWARD_ITERATOR
        requires(std::forward_iterator<iterator>)
#endif
    {
        fill_kvp_buffer();
    }

    /**
     * Returns the number of key-value pairs.
     */
    consteval auto size() const noexcept {
        return kvpcount();
    }

    constexpr auto begin() const noexcept {
        return iterator(kvp_buffer);
    }
    constexpr auto end() const noexcept {
        return iterator(kvp_buffer + sizeof(kvp_buffer) / sizeof(char_type) - 1);
    }
    constexpr auto cbegin() const noexcept {
        return begin();
    }
    constexpr auto cend() const noexcept {
        return end();
    }

    /**
     * Returns beginning iterator for the given section.
     */
    constexpr auto begin(const char_type *section) const noexcept {
        auto it = begin();
        do {
            if (it->section != NULL && stringmatch(it->section, section))
                break;
        } while (++it != end());
        return it;
    }

    /** 
     * Returns end iterator for the given section.
     */
    constexpr auto end(const char_type *section) const noexcept {
        auto it = begin(section);
        while (++it != end() && stringmatch(it->section, section));
        return it;
    }

    class section_view {
        iterator m_begin;
        iterator m_end;
    public:
        constexpr section_view(const ini_config& ini, const char_type *section)
            : m_begin(ini.begin(section)), m_end(ini.end(section)) {}
        constexpr auto begin() const noexcept {
            return m_begin;
        }
        constexpr auto end() const noexcept {
            return m_end;
        }
    };

    /**
     * Creates a 'view' for the given section, for use with ranged for.
     */
    constexpr auto section(const char_type *s) const noexcept {
        return section_view(*this, s);
    }

    /**
     * Returns the value for the given key as a string.
     * Returns "" if key does not exist.
     */
    consteval auto get(const char_type *key) const noexcept {
        for (auto kvp : *this) {
            if (stringmatch(kvp.first, key))
                return kvp.second;
        }
        return "";
    }
    /**
     * Returns the value for the given key, converted to the given type.
     * Returns zero if key does not exist.
     */
    template<typename T> requires(std::integral<T> || std::floating_point<T>)
    consteval T get(const char_type *key) const noexcept {
        return from_string<T>(get(key));
    }
    /**
     * Returns the value for the given key in the given section.
     * Returns "" on failure.
     */
    consteval auto get(const char_type *sec, const char_type *key) const noexcept {
        for (auto kvp : section(sec)) {
            if (stringmatch(kvp.first, key))
                return kvp.second;
        }
        return "";
    }
    /**
     * Returns the value for the given key in the given section,
     * converting it to the specified type.
     * Returns zero on failure.
     */
    template<typename T> requires(std::integral<T> || std::floating_point<T>)
    consteval T get(const char_type *sec, const char_type *key) const noexcept {
        return from_string<T>(get(sec, key));
    }

    /**
     * tryget() calls are for run-time use when 'sec' or 'key'
     * is not known at compile-time.
     */
    auto tryget(const char_type *key) const noexcept {
        for (auto kvp : *this) {
            if (stringmatch(kvp.first, key))
                return kvp.second;
        }
        return "";
    }
    template<typename T> requires(std::integral<T> || std::floating_point<T>)
    T tryget(const char_type *key) const noexcept {
        return from_string<T>(tryget(key));
    }
    auto tryget(const char_type *sec, const char_type *key) const noexcept {
        for (auto kvp : section(sec)) {
            if (stringmatch(kvp.first, key))
                return kvp.second;
        }
        return "";
    }
    template<typename T> requires(std::integral<T> || std::floating_point<T>)
    T tryget(const char_type *sec, const char_type *key) const noexcept {
        return from_string<T>(tryget(sec, key));
    }

    consteval bool contains(const char_type *key) const noexcept {
        return *get(key) != '\0';
    }
    consteval bool contains(const char_type *sec, const char_type *key) const noexcept {
        return *get(sec, key) != '\0';
    }
    bool trycontains(const char_type *key) const noexcept {
        return *tryget(key) != '\0';
    }
    bool trycontains(const char_type *sec, const char_type *key) const noexcept {
        return *tryget(sec, key) != '\0';
    }
};

} // namespace ini_config

/**
 * _ini suffix definition.
 */
template <ini_config::string_container Input>
consteval auto operator ""_ini()
{
    return ini_config::ini_config<Input>();
}

// For MSVC, the below alternative seems promising, though
// MSVC v19.28 complains about running out of heap.
template <ini_config::string_container Input>
constexpr auto make_ini_config = ini_config::ini_config<Input>();

#endif // TCSULLIVAN_INI_CONFIG_HPP

#include <LSM303.h>
#include <Wire.h>
#include <math.h>

// Defines ////////////////////////////////////////////////////////////////

// The Arduino two-wire interface uses a 7-bit number for the address,
// and sets the last bit correctly based on reads and writes
#define D_SA0_HIGH_ADDRESS                0b0011101
#define D_SA0_LOW_ADDRESS                 0b0011110
#define DLHC_DLM_DLH_MAG_ADDRESS          0b0011110
#define DLHC_DLM_DLH_ACC_SA0_HIGH_ADDRESS 0b0011001
#define DLM_DLH_ACC_SA0_LOW_ADDRESS       0b0011000

#define TEST_REG_ERROR -1

#define D_WHO_ID    0x49
#define DLM_WHO_ID  0x3C

// Constructors ////////////////////////////////////////////////////////////////

LSM303::LSM303(void)
{
  /*
  These values lead to an assumed magnetometer bias of 0.
  Use the Calibrate example program to determine appropriate values
  for your particular unit. The Heading example demonstrates how to
  adjust these values in your own sketch.
  */
  m_min = (LSM303::vector<int16_t>){-32767, -32767, -32767};
  m_max = (LSM303::vector<int16_t>){+32767, +32767, +32767};

  _device = device_auto;

  io_timeout = 0;  // 0 = no timeout
  did_timeout = false;
}

// Public Methods //////////////////////////////////////////////////////////////

// Did a timeout occur in readAcc(), readMag(), or read() since the last call to timeoutOccurred()?
bool LSM303::timeoutOccurred()
{
  bool tmp = did_timeout;
  did_timeout = false;
  return tmp;
}

void LSM303::setTimeout(unsigned int timeout)
{
  io_timeout = timeout;
}

unsigned int LSM303::getTimeout()
{
  return io_timeout;
}

bool LSM303::init(deviceType device, sa0State sa0)
{
  // perform auto-detection unless device type and SA0 state were both specified
  if (device == device_auto || sa0 == sa0_auto)
  {
    // check for LSM303D if device is unidentified or was specified to be this type
    if (device == device_auto || device == device_D)
    {
      // check SA0 high address unless SA0 was specified to be low
      if (sa0 != sa0_low && testReg(D_SA0_HIGH_ADDRESS, WHO_AM_I) == D_WHO_ID)
      {
        // device responds to address 0011101 with D ID; it's a D with SA0 high
        device = device_D;
        sa0 = sa0_high;
      }
      // check SA0 low address unless SA0 was specified to be high
      else if (sa0 != sa0_high && testReg(D_SA0_LOW_ADDRESS, WHO_AM_I) == D_WHO_ID)
      {
        // device responds to address 0011110 with D ID; it's a D with SA0 low
        device = device_D;
        sa0 = sa0_low;
      }
    }

    // check for LSM303DLHC, DLM, DLH if device is still unidentified or was specified to be one of these types
    if (device == device_auto || device == device_DLHC || device == device_DLM || device == device_DLH)
    {
      // check SA0 high address unless SA0 was specified to be low
      if (sa0 != sa0_low && testReg(DLHC_DLM_DLH_ACC_SA0_HIGH_ADDRESS, CTRL_REG1_A) != TEST_REG_ERROR)
      {
        // device responds to address 0011001; it's a DLHC, DLM with SA0 high, or DLH with SA0 high
        sa0 = sa0_high;
        if (device == device_auto)
        { 
          // use magnetometer WHO_AM_I register to determine device type
          //
          // DLHC seems to respond to WHO_AM_I request the same way as DLM, even though this
          // register isn't documented in its datasheet. Since the DLHC accelerometer address is the
          // same as the DLM with SA0 high, but Pololu DLM boards pull SA0 low by default, we'll
          // guess that a device whose accelerometer responds to the SA0 high address and whose
          // magnetometer gives the DLM ID is actually a DLHC.
          device = (testReg(DLHC_DLM_DLH_MAG_ADDRESS, WHO_AM_I_M) == DLM_WHO_ID) ? device_DLHC : device_DLH;
        }
      }
      // check SA0 low address unless SA0 was specified to be high
      else if (sa0 != sa0_high && testReg(DLM_DLH_ACC_SA0_LOW_ADDRESS, CTRL_REG1_A) != TEST_REG_ERROR)
      {
        // device responds to address 0011000; it's a DLM with SA0 low or DLH with SA0 low
        sa0 = sa0_low;
        if (device == device_auto)
        {
          // use magnetometer WHO_AM_I register to determine device type
          device = (testReg(DLHC_DLM_DLH_MAG_ADDRESS, WHO_AM_I_M) == DLM_WHO_ID) ? device_DLM : device_DLH;
        }
      }
    }

    // make sure device and SA0 were successfully detected; otherwise, indicate failure
    if (device == device_auto || sa0 == sa0_auto)
    {
      return false;
    }
  }

  _device = device;

  // set device addresses and translated register addresses
  switch (device)
  {
    case device_D:
      acc_address = mag_address = (sa0 == sa0_high) ? D_SA0_HIGH_ADDRESS : D_SA0_LOW_ADDRESS;
      translated_regs[-OUT_X_L_M] = D_OUT_X_L_M;
      translated_regs[-OUT_X_H_M] = D_OUT_X_H_M;
      translated_regs[-OUT_Y_L_M] = D_OUT_Y_L_M;
      translated_regs[-OUT_Y_H_M] = D_OUT_Y_H_M;
      translated_regs[-OUT_Z_L_M] = D_OUT_Z_L_M;
      translated_regs[-OUT_Z_H_M] = D_OUT_Z_H_M;
      break;

    case device_DLHC:
      acc_address = DLHC_DLM_DLH_ACC_SA0_HIGH_ADDRESS; // DLHC doesn't have configurable SA0 but uses same acc address as DLM/DLH with SA0 high
      mag_address = DLHC_DLM_DLH_MAG_ADDRESS;
      translated_regs[-OUT_X_H_M] = DLHC_OUT_X_H_M;
      translated_regs[-OUT_X_L_M] = DLHC_OUT_X_L_M;
      translated_regs[-OUT_Y_H_M] = DLHC_OUT_Y_H_M;
      translated_regs[-OUT_Y_L_M] = DLHC_OUT_Y_L_M;
      translated_regs[-OUT_Z_H_M] = DLHC_OUT_Z_H_M;
      translated_regs[-OUT_Z_L_M] = DLHC_OUT_Z_L_M;
      break;

    case device_DLM:
      acc_address = (sa0 == sa0_high) ? DLHC_DLM_DLH_ACC_SA0_HIGH_ADDRESS : DLM_DLH_ACC_SA0_LOW_ADDRESS;
      mag_address = DLHC_DLM_DLH_MAG_ADDRESS;
      translated_regs[-OUT_X_H_M] = DLM_OUT_X_H_M;
      translated_regs[-OUT_X_L_M] = DLM_OUT_X_L_M;
      translated_regs[-OUT_Y_H_M] = DLM_OUT_Y_H_M;
      translated_regs[-OUT_Y_L_M] = DLM_OUT_Y_L_M;
      translated_regs[-OUT_Z_H_M] = DLM_OUT_Z_H_M;
      translated_regs[-OUT_Z_L_M] = DLM_OUT_Z_L_M;
      break;

    case device_DLH:
      acc_address = (sa0 == sa0_high) ? DLHC_DLM_DLH_ACC_SA0_HIGH_ADDRESS : DLM_DLH_ACC_SA0_LOW_ADDRESS;
      mag_address = DLHC_DLM_DLH_MAG_ADDRESS;
      translated_regs[-OUT_X_H_M] = DLH_OUT_X_H_M;
      translated_regs[-OUT_X_L_M] = DLH_OUT_X_L_M;
      translated_regs[-OUT_Y_H_M] = DLH_OUT_Y_H_M;
      translated_regs[-OUT_Y_L_M] = DLH_OUT_Y_L_M;
      translated_regs[-OUT_Z_H_M] = DLH_OUT_Z_H_M;
      translated_regs[-OUT_Z_L_M] = DLH_OUT_Z_L_M;
      break;
  }

  return true;
}

/*
Enables the LSM303's accelerometer and magnetometer. Also:
- Sets sensor full scales (gain) to default power-on values, which are
  +/- 2 g for accelerometer and +/- 1.3 gauss for magnetometer
  (+/- 4 gauss on LSM303D).
- Selects 50 Hz ODR (output data rate) for accelerometer and 7.5 Hz
  ODR for magnetometer (6.25 Hz on LSM303D). (These are the ODR
  settings for which the electrical characteristics are specified in
  the datasheets.)
- Enables high resolution modes (if available).
Note that this function will also reset other settings controlled by
the registers it writes to.
*/
void LSM303::enableDefault(void)
{

  if (_device == device_D)
  {
    // Accelerometer

    // 0x00 = 0b00000000
    // AFS = 0 (+/- 2 g full scale)
    writeReg(CTRL2, 0x00);

    // 0x57 = 0b01010111
    // AODR = 0101 (50 Hz ODR); AZEN = AYEN = AXEN = 1 (all axes enabled)
    writeReg(CTRL1, 0x57);

    // Magnetometer

    // 0x64 = 0b01100100
    // M_RES = 11 (high resolution mode); M_ODR = 001 (6.25 Hz ODR)
    writeReg(CTRL5, 0x64);

    // 0x20 = 0b00100000
    // MFS = 01 (+/- 4 gauss full scale)
    writeReg(CTRL6, 0x20);

    // 0x00 = 0b00000000
    // MLP = 0 (low power mode off); MD = 00 (continuous-conversion mode)
    writeReg(CTRL7, 0x00);
  }
  else
  {
    // Accelerometer

    if (_device == device_DLHC)
    {
      // 0x08 = 0b00001000
      // FS = 00 (+/- 2 g full scale); HR = 1 (high resolution enable)
      writeAccReg(CTRL_REG4_A, 0x08);

      // 0x47 = 0b01000111
      // ODR = 0100 (50 Hz ODR); LPen = 0 (normal mode); Zen = Yen = Xen = 1 (all axes enabled)
      writeAccReg(CTRL_REG1_A, 0x47);
    }
    else // DLM, DLH
    {
      // 0x00 = 0b00000000
      // FS = 00 (+/- 2 g full scale)
      writeAccReg(CTRL_REG4_A, 0x00);

      // 0x27 = 0b00100111
      // PM = 001 (normal mode); DR = 00 (50 Hz ODR); Zen = Yen = Xen = 1 (all axes enabled)
      writeAccReg(CTRL_REG1_A, 0x27);
    }

    // Magnetometer

    // 0x0C = 0b00001100
    // DO = 011 (7.5 Hz ODR)
    writeMagReg(CRA_REG_M, 0x0C);

    // 0x20 = 0b00100000
    // GN = 001 (+/- 1.3 gauss full scale)
    writeMagReg(CRB_REG_M, 0x20);

    // 0x00 = 0b00000000
    // MD = 00 (continuous-conversion mode)
    writeMagReg(MR_REG_M, 0x00);
  }
}

// Writes an accelerometer register
void LSM303::writeAccReg(byte reg, byte value)
{
  Wire.beginTransmission(acc_address);
  Wire.write(reg);
  Wire.write(value);
  last_status = Wire.endTransmission();
}

// Reads an accelerometer register
byte LSM303::readAccReg(byte reg)
{
  byte value;

  Wire.beginTransmission(acc_address);
  Wire.write(reg);
  last_status = Wire.endTransmission();
  Wire.requestFrom(acc_address, (byte)1);
  value = Wire.read();
  Wire.endTransmission();

  return value;
}

// Writes a magnetometer register
void LSM303::writeMagReg(byte reg, byte value)
{
  Wire.beginTransmission(mag_address);
  Wire.write(reg);
  Wire.write(value);
  last_status = Wire.endTransmission();
}

// Reads a magnetometer register
byte LSM303::readMagReg(int reg)
{
  byte value;

  // if dummy register address (magnetometer Y/Z), look up actual translated address (based on device type)
  if (reg < 0)
  {
    reg = translated_regs[-reg];
  }

  Wire.beginTransmission(mag_address);
  Wire.write(reg);
  last_status = Wire.endTransmission();
  Wire.requestFrom(mag_address, (byte)1);
  value = Wire.read();
  Wire.endTransmission();

  return value;
}

void LSM303::writeReg(byte reg, byte value)
{
  // mag address == acc_address for LSM303D, so it doesn't really matter which one we use.
  if (_device == device_D || reg < CTRL_REG1_A)
  {
    writeMagReg(reg, value);
  }
  else
  {
    writeAccReg(reg, value);
  }
}

// Note that this function will not work for reading TEMP_OUT_H_M and TEMP_OUT_L_M on the DLHC.
// To read those two registers, use readMagReg() instead.
byte LSM303::readReg(int reg)
{
  // mag address == acc_address for LSM303D, so it doesn't really matter which one we use.
  // Use readMagReg so it can translate OUT_[XYZ]_[HL]_M
  if (_device == device_D || reg < CTRL_REG1_A)
  {
    return readMagReg(reg);
  }
  else
  {
    return readAccReg(reg);
  }
}

// Reads the 3 accelerometer channels and stores them in vector a
void LSM303::readAcc(void)
{
  Wire.beginTransmission(acc_address);
  // assert the MSB of the address to get the accelerometer
  // to do slave-transmit subaddress updating.
  Wire.write(OUT_X_L_A | (1 << 7));
  last_status = Wire.endTransmission();
  Wire.requestFrom(acc_address, (byte)6);

  unsigned int millis_start = millis();
  while (Wire.available() < 6) {
    if (io_timeout > 0 && ((unsigned int)millis() - millis_start) > io_timeout)
    {
      did_timeout = true;
      return;
    }
  }

  byte xla = Wire.read();
  byte xha = Wire.read();
  byte yla = Wire.read();
  byte yha = Wire.read();
  byte zla = Wire.read();
  byte zha = Wire.read();

  // combine high and low bytes
  // This no longer drops the lowest 4 bits of the readings from the DLH/DLM/DLHC, which are always 0
  // (12-bit resolution, left-aligned). The D has 16-bit resolution
  a.x = (int16_t)(xha << 8 | xla);
  a.y = (int16_t)(yha << 8 | yla);
  a.z = (int16_t)(zha << 8 | zla);
}

// Reads the 3 magnetometer channels and stores them in vector m
void LSM303::readMag(void)
{
  Wire.beginTransmission(mag_address);
  // If LSM303D, assert MSB to enable subaddress updating
  // OUT_X_L_M comes first on D, OUT_X_H_M on others
  Wire.write((_device == device_D) ? translated_regs[-OUT_X_L_M] | (1 << 7) : translated_regs[-OUT_X_H_M]);
  last_status = Wire.endTransmission();
  Wire.requestFrom(mag_address, (byte)6);

  unsigned int millis_start = millis();
  while (Wire.available() < 6) {
    if (io_timeout > 0 && ((unsigned int)millis() - millis_start) > io_timeout)
    {
      did_timeout = true;
      return;
    }
  }

  byte xlm, xhm, ylm, yhm, zlm, zhm;

  if (_device == device_D)
  {
    // D: X_L, X_H, Y_L, Y_H, Z_L, Z_H
    xlm = Wire.read();
    xhm = Wire.read();
    ylm = Wire.read();
    yhm = Wire.read();
    zlm = Wire.read();
    zhm = Wire.read();
  }
  else
  {
    // DLHC, DLM, DLH: X_H, X_L...
    xhm = Wire.read();
    xlm = Wire.read();

    if (_device == device_DLH)
    {
      // DLH: ...Y_H, Y_L, Z_H, Z_L
      yhm = Wire.read();
      ylm = Wire.read();
      zhm = Wire.read();
      zlm = Wire.read();
    }
    else
    {
      // DLM, DLHC: ...Z_H, Z_L, Y_H, Y_L
      zhm = Wire.read();
      zlm = Wire.read();
      yhm = Wire.read();
      ylm = Wire.read();
    }
  }

  // combine high and low bytes
  m.x = (int16_t)(xhm << 8 | xlm);
  m.y = (int16_t)(yhm << 8 | ylm);
  m.z = (int16_t)(zhm << 8 | zlm);
}

// Reads all 6 channels of the LSM303 and stores them in the object variables
void LSM303::read(void)
{
  readAcc();
  readMag();
}

/*
Returns the angular difference in the horizontal plane between a
default vector and north, in degrees.

The default vector here is chosen to point along the surface of the
PCB, in the direction of the top of the text on the silkscreen.
This is the +X axis on the Pololu LSM303D carrier and the -Y axis on
the Pololu LSM303DLHC, LSM303DLM, and LSM303DLH carriers.
*/
float LSM303::heading(void)
{
  if (_device == device_D)
  {
    return heading((vector<int>){1, 0, 0});
  }
  else
  {
    return heading((vector<int>){0, -1, 0});
  }
}

void LSM303::vector_normalize(vector<float> *a)
{
  float mag = sqrt(vector_dot(a, a));
  a->x /= mag;
  a->y /= mag;
  a->z /= mag;
}

// Private Methods //////////////////////////////////////////////////////////////

int LSM303::testReg(byte address, regAddr reg)
{
  Wire.beginTransmission(address);
  Wire.write((byte)reg);
  if (Wire.endTransmission() != 0)
  {
    return TEST_REG_ERROR;
  }

  Wire.requestFrom(address, (byte)1);
  if (Wire.available())
  {
    return Wire.read();
  }
  else
  {
    return TEST_REG_ERROR;
  }
}

#include "stafflist.h"
#include <QPushButton>
#include <QFontDatabase>
StaffList::StaffList(QWidget *parent)
    : QWidget{parent}
{
    addStaff();
}
void StaffList::addStaff() { //Composed with basic coding tools
    bool isFirstStaff = staffL.isEmpty(); // Check if it's the first staff added
    Staff* elem = new Staff(this);
    elem->initStaff();
    staffL.append(elem);
    qDebug() << "Staff added. Total staff count: " << staffL.size();
    this->setMinimumSize(800, this->height() + 110);
    int staffIndex = staffL.size() - 1;
    int staffWidth = elem->width();  // Replace with the actual width of the staff element
    int staffHeight = elem->height();  // Replace with the actual height of the staff element
    int spacing = 10;  // Adjust the spacing value as needed
    int posY = staffIndex * (staffHeight + spacing);
    elem->setGeometry(0, posY, staffWidth, staffHeight);
    elem->setVisible(true);

    if (isFirstStaff) {
        QFontDatabase::addApplicationFont(":/fonts/Leland.otf");
    }
}
Staff* StaffList::getStaff(int n){
    if (n>=0){
    return staffL[n];
    }

    else{
        return staffL[staffL.size() + n];
    }
}

Staff* StaffList::operator [](int n){
    return getStaff(n);
}

/*
DGS.cpp - Library for reading KWJ Engineering with SPEC Sensors on Digital SDK.
Created by David E. Peaslee, NOV 27, 2016.
Updated by David Peaslee, MAR 24, 2021
*/

/*
User inputs are 
'\r'
'c' set to continuous approx. 4 mA to ground (not including uart consumption)
'S' set span accepts a PPM float above 1.0 "\r\nEnter span gas value in PPM:" atof() "\r\nSetting span..." then:
                      either "done\r\n" or "Temperature error, " or "ADC range error, " or "Serial number error, " & "no changes made\r\n"
'Z' zero sensor "\r\nSetting zero..." either "done\r\n", "Temperature error, " or "ADC range error, " and "no changes made\r\n"
'f' output firmware should be "15SEP17\r\n"
'l' get LMP values: "                               LMP91000 Values\r\n", "LMP91000 Register 0x10= 3\r\n","LMP91000 Register 0x11= 145\r\n","LMP91000 Register 0x12= 3\r\n"
'L' set LMP values: "\r\nEnter LMP91000 Register 0x10:",atoi(),"\r\nEnter LMP91000 Register 0x11:",atoi(),"\r\nEnter LMP91000 Register 0x12:",atoi(),"\r\n"
'T' set Temperature offset: "\r\nEnter Temperature_Offset: ", atof(), "\r\n"
'A' set average: "\r\nEnter Average Total: ", atoi(), "\r\n"
'B' set Barcode: "\r\nRemove Sensor and Scan: ", BC,"\r\nSetting OC...done\r\nSetting zero...done\r\n"
'e' get eeprom: "                               EEPROM Values\r\n"
        nA_per_PPM_x100= 340
        ADC_OC= 13035
        ADC_Zero= 13035
        ADC_Span= 16299
        Temperature_Offset_x1000= 1000
        T_Zero= 25336
        RH_Zero= 27602
        T_Span= 25052
        RH_Span= 27710
        LMP91000 Register 0x10= 3
        LMP91000 Register 0x11= 145
        LMP91000 Register 0x12= 3
        Average_Total= 1
        Barcode= 042617040460 110102 CO 1705 2.72
        Serial_Number= 042617040460
        Part_Number= 110102
        Gas= CO
        Date_Code= 1705
        Sensitivity_Code= 2.72\r\n
'r' reset: locks to reset WDT
's' sleep approx. 30 uA to ground
*/

#include "DGS.h"

DGS::DGS(Stream *mySerial) : _mySerial(mySerial) {
	isSleeping = false;
}

DGS::DGS(Stream &mySerial) : _mySerial(&mySerial) {
	isSleeping = false;
}

void DGS::unlock(void)
{
  DEBUG_PRINT("Unlocking");
  _mySerial->write("12345\r");
  delay(500);
}

void DGS::DEBUG_PRINTLN(long x)
{
  if (DEBUG) {
    delay(10);
    Serial.println(x);
  }
}

void DGS::DEBUG_PRINTLN(String x)
{
  if (DEBUG) {
    delay(10);
    Serial.println(x);
  }
}

void DGS::DEBUG_PRINTLN(float x)
{
  if (DEBUG) {
    delay(10);
    Serial.println(x);
  }
}

void DGS::DEBUG_PRINT(long x)
{
  if (DEBUG) {
    delay(10);
    Serial.print(x);
  }
}

void DGS::DEBUG_PRINT(float x)
{
  if (DEBUG) {
    delay(10);
    Serial.print(x);
  }
}

void DGS::DEBUG_PRINT(String x)
{
  if (DEBUG) {
    delay(10);
    Serial.print(x);
  }
}

int DGS::getData(char c)
{
  delay(500);
  String dataString;
  _mySerial->write(c);
  while (!_mySerial->available()) {
  }
  dataString = _mySerial->readStringUntil('\n');
  for (int i = 0; i < 11; i++) {
    String subS = dataString.substring(0, dataString.indexOf(','));
    if (subS.length() == 0) return 0;
    dataArray[i] = subS.toInt();
    dataString = dataString.substring(dataString.indexOf(',') + 2);
  }
  return 1;
}
void DGS::sleepSensor(unsigned long sleepy)
{
  isSleeping = true;
  sleepTime = (1000 * sleepy) + millis();
  DEBUG_PRINTLN("Going to Sleep");
  while (_mySerial->available()) _mySerial->read();
  _mySerial->write('s');  
}

bool DGS::wakeSensor(void)
{
  if (isSleeping && (millis() > sleepTime)){
	  isSleeping = false;
	  DEBUG_PRINTLN("Waking");
	  while (_mySerial->available()) _mySerial->read();
	  _mySerial->write('r');
	  delay(2000);
  } 
  return !isSleeping;
}

int DGS::setToff(float offset)
{
  String commandString;
  DEBUG_PRINTLN("Starting T Offset");
  while (_mySerial->available()) _mySerial->read();
  _mySerial->write('T');
  delay(10);
  while (!_mySerial->available()) {}
  commandString = _mySerial->readString();
  DEBUG_PRINT(commandString);

  delay(100);
  if (commandString == "\r\nEnter Temperature_Offset: ") {
    _mySerial->println(offset);
//    _mySerial->write('\r');
  }
  else {
    DEBUG_PRINTLN("Failed Entering Temperature");

    delay(2000);
    while (_mySerial->available()) _mySerial->read();
    return 0;

  }

  while (!_mySerial->available()) {}
  commandString = _mySerial->readString();
  DEBUG_PRINTLN(commandString);
  return 1;

}

int DGS::setBC(const char *BC)
{
  String commandString;
  DEBUG_PRINTLN("Starting BC Setup");
  while (_mySerial->available()) _mySerial->read();
  _mySerial->write('B');
  while (!_mySerial->available()) {}
  commandString = _mySerial->readString();
  DEBUG_PRINT(commandString);

  if (commandString == "\r\nRemove Sensor and Scan: ") {

    for (int i = 0; i < (int) strlen(BC); i++) {
      _mySerial->write(BC[i]);

      delay(10);
    }
    _mySerial->write('\r');
  }
  else {
    DEBUG_PRINTLN("Failed Entering BC");
    return 0;
  }
  while (!_mySerial->available()) {}
  commandString = _mySerial->readStringUntil('\n');
  DEBUG_PRINTLN(commandString); //should be \r\n

  while (!_mySerial->available()) {}
  commandString = _mySerial->readStringUntil('\n');
  DEBUG_PRINTLN(commandString); 

  while (!_mySerial->available()) {}
  commandString = _mySerial->readString();
  DEBUG_PRINT(commandString); 

  if (commandString == "Setting zero...done\r\n") {
    delay(2000);
    DEBUG_PRINTLN("Success");
    return 1;
  }
  delay(2000);
  return 0;
}

void DGS::getEEPROM(void)
{
  DEBUG_PRINTLN("Starting EEPROM Read");
  while (_mySerial->available()) _mySerial->read();
  _mySerial->flush();
  _mySerial->write('e');

  while (!_mySerial->available()) {}

  String data = _mySerial->readStringUntil('\n');
  DEBUG_PRINTLN(data);
  while (!_mySerial->available()) {}
  for (int i = 1; i < 14; i++) {
    data = _mySerial->readStringUntil('\n');
    String subS1 = data.substring(0, data.indexOf('='));
    String subS2 = data.substring(data.indexOf('=') + 2);
    eepromInt[i] = subS2.toInt();
    DEBUG_PRINT(subS1);
    DEBUG_PRINT("= ");
    DEBUG_PRINTLN(eepromInt[i]);
  }
  for (int i = 14; i < 19; i++) {
    data = _mySerial->readStringUntil('\n');
    String subS1 = data.substring(0, data.indexOf('='));
    String subS2 = data.substring(data.indexOf('=') + 2);
    eepromStr[i - 14] = subS2;
    DEBUG_PRINT(subS1);
    DEBUG_PRINT("= ");
    DEBUG_PRINTLN(eepromStr[i - 14]);
  }
  data = _mySerial->readStringUntil('\n');
  String subS1 = data.substring(0, data.indexOf('='));
  String subS2 = data.substring(data.indexOf('=') + 2);
  Sensitivity_Code = subS2.toFloat();
  DEBUG_PRINT(subS1);
  DEBUG_PRINT("= ");
  DEBUG_PRINTLN(Sensitivity_Code);
  while (_mySerial->available()) _mySerial->read();

}

String DGS::getFW(void)
{
  String dataString;
  DEBUG_PRINTLN("Getting FW");
  while (_mySerial->available()) _mySerial->read();
  _mySerial->flush();
  _mySerial->write('f');

  while (!_mySerial->available()) {}
  dataString = _mySerial->readStringUntil('\r');
  if (dataString != "15SEP17") DEBUG_PRINTLN("Unsupported FW");
  while (_mySerial->available()) _mySerial->read();
  return dataString;
}

int DGS::setLMP(int R1, int R2, int R3)
{
  String commandString;
  DEBUG_PRINTLN("Setting LMP Registers");
  while (_mySerial->available()) _mySerial->read();
  _mySerial->flush();
  _mySerial->write('L');

  while (!_mySerial->available()) {}
  commandString = _mySerial->readStringUntil('\n');
  commandString = _mySerial->readStringUntil('\n');
  commandString.trim();
  DEBUG_PRINT(commandString);
  if (commandString == "Enter LMP91000 Register 0x10:") {
    _mySerial->print(R1);
	_mySerial->print("\r");
  }
  else {
    DEBUG_PRINTLN("Setting Failed");
    return 0;
  }
  while (!_mySerial->available()) {}
  commandString = _mySerial->readStringUntil('\n');
  DEBUG_PRINTLN(commandString);
  if (commandString.toInt() != R1) {
    DEBUG_PRINTLN("Failure");
    return 0;
  }

  while (!_mySerial->available()) {}
  commandString = _mySerial->readStringUntil('\n');
  commandString.trim();
  DEBUG_PRINT(commandString);
  if (commandString == "Enter LMP91000 Register 0x11:") {
    _mySerial->print(R2);
	_mySerial->print("\r");
  }
  else {
    DEBUG_PRINTLN("Setting Failed");
    return 0;
  }
  while (!_mySerial->available()) {}
  commandString = _mySerial->readStringUntil('\n');
  DEBUG_PRINTLN(commandString);
  if (commandString.toInt() != R2) {
    DEBUG_PRINTLN("Failure");
    return 0;
  }

while (!_mySerial->available()) {}
  commandString = _mySerial->readStringUntil('\n');
  commandString.trim();
  DEBUG_PRINT(commandString);
  if (commandString == "Enter LMP91000 Register 0x12:") {
    _mySerial->print(R3); 
	_mySerial->print("\r");
  }
  else {
    DEBUG_PRINTLN("Setting Failed");
    return 0;
  }
  while (!_mySerial->available()) {}
  commandString = _mySerial->readString();
  commandString.trim();
  DEBUG_PRINTLN(commandString);
  if (commandString.toInt() != R3) {
    DEBUG_PRINTLN("Failure");
    return 0;
  }

  else {
    while (_mySerial->available()) _mySerial->read();
    DEBUG_PRINTLN("Success");
    delay(2000);
    return 1;
  }
}

int DGS::getLMP(void)
{
  String dataString;
  DEBUG_PRINTLN("Getting LMP Registers");
  while (_mySerial->available()) _mySerial->read();
  _mySerial->flush();
  _mySerial->write('l');

  while (!_mySerial->available()) {}
  dataString = _mySerial->readStringUntil('\n');
  DEBUG_PRINTLN(dataString);

  while (!_mySerial->available()) {}
  //"LMP91000 Register 0x1X= 3\r\n"
  for (int i = 0; i < 3; i++) {
    dataString = _mySerial->readStringUntil('\n');
    String subS = dataString.substring(dataString.indexOf('=') + 1, dataString.length());
    LMP[i] = subS.toInt();
    DEBUG_PRINT("LMP R");
    DEBUG_PRINT((long)i);
    DEBUG_PRINT(" = ");
    DEBUG_PRINTLN((long)LMP[i]);
    if (LMP[i] < 3 || LMP[i] > 200) return 0;
  }
  return 1;
}

int DGS::zero(void)
{
  String commandString;
  DEBUG_PRINTLN("Starting Zero");
  while (_mySerial->available()) _mySerial->read();
  _mySerial->flush();

  _mySerial->write('Z');

  //should be \r\nSetting zero..." either "done\r\n
  while (!_mySerial->available()) {}
  commandString = _mySerial->readStringUntil('\n');
  DEBUG_PRINTLN(commandString);

  delay(10);

  while (!_mySerial->available()) {}
  commandString = _mySerial->readStringUntil('\n');
  DEBUG_PRINTLN(commandString); 

  if (commandString == "Setting zero...done\r") {
    DEBUG_PRINTLN("Success");
    return 1;
  }
  else DEBUG_PRINTLN("Failed Zero");
  return 0;
}

int DGS::setXSpan(float X)
{
  String commandString;
  float inSf;
  DEBUG_PRINTLN("Starting Span Setup");
  while (_mySerial->available()) _mySerial->read();
  _mySerial->write('S');

  while (!_mySerial->available()) {}
  commandString = _mySerial->readString();
  DEBUG_PRINT(commandString);
  delay(10);
  if (commandString == "Enter Unlock Code: ") {
    unlock();
  }
/*   else {
    DEBUG_PRINT("Failed Unlock");
    return 0;
  } */

  while (!_mySerial->available()) {}
  commandString = _mySerial->readString();
  DEBUG_PRINT(commandString);
  delay(10);
  if (commandString == "\r\nEnter span gas value in PPM: ") {
    _mySerial->print(X);
    _mySerial->write('\r');
  }
  else {
    DEBUG_PRINT("Failed Span");
    return 0;
  }
  while (!_mySerial->available()) {}
  inSf = _mySerial->parseFloat();
  DEBUG_PRINT(inSf);

  commandString = _mySerial->readString();
  DEBUG_PRINT(commandString);

  if (inSf == X)
  {

  }
  while (!_mySerial->available()) {
    delay(1);
  }
  commandString = _mySerial->readString();
  DEBUG_PRINT(commandString);
  delay(10);
  if (commandString == "done\r\n") {
    DEBUG_PRINTLN("Success");
    return 1;
  }
  else DEBUG_PRINTLN("Failed Span");
  return 0;

  delay(10);
}

long DGS::getConc(char u)
{
  if (u == 'c') return dataArray[4];  //returns counts
  else return dataArray[1];
}

int DGS::setAve(int t)
{
	if (t>300) t = 300;
	else if (t<1) t = 1;
	String commandString;
	DEBUG_PRINTLN("Setting Average time (range: 1-300 seconds)");
	while (_mySerial->available()) _mySerial->read();
	_mySerial->write('A');

	while (!_mySerial->available()) {}
	commandString = _mySerial->readString();
	DEBUG_PRINT(commandString);

	if (commandString == "\r\nEnter Average Total: ") {
		_mySerial->print(t);
		_mySerial->write('\r');
		delay(100);

	}
	else {
		while (_mySerial->available()) _mySerial->read();
		DEBUG_PRINTLN("Failed setting Average");
		return 0;
	}
	while (!_mySerial->available()) {}
	commandString = _mySerial->readStringUntil('\n');
	DEBUG_PRINTLN(commandString); 
	return 1;
}

float DGS::getTemp(char u)
{	
  if (u == 'c') return dataArray[2]; //return integer in degC
  float temp = dataArray[5]/65536.0*175.72;
  temp = temp - 46.85;
  if (u == 'F') return temp * 9 / 5 + 32;
  else return temp; //return counts converted to C
}

float DGS::getRh(char u)
{
  if (u == 'r') return dataArray[3];
  float humid = dataArray[6]/65536.0*125.0;
  humid = humid - 6.0;
  return humid;
}

