        constexpr TVec3& operator-=(const TVec3& rhs) {
            this->x() -= rhs.x();
            this->y() -= rhs.y();
            this->z() -= rhs.z();
            return *this;
        }

        // Scalar operations
        constexpr TVec3 operator*(T rhs) const {
