/*
  This code was taken from the original github crypto-master zip file and slightly 
  modified to return a size_t type from the Sha1Class.write() call.

  https://github.com/Cathedrow/Cryptosuite

  The original code to the Cryptosuite library is contained within the 
  Cryptosuite-master sub-directory with the needed sha1.h/cpp files copied
  from there and modified as described above.
*/
#include <string.h>
//#include <avr/io.h>
//#include <avr/pgmspace.h>
#include "sha1.h"

#define SHA1_K0 0x5a827999
#define SHA1_K20 0x6ed9eba1
#define SHA1_K40 0x8f1bbcdc
#define SHA1_K60 0xca62c1d6

const uint8_t sha1InitState[] PROGMEM = {
  0x01,0x23,0x45,0x67, // H0
  0x89,0xab,0xcd,0xef, // H1
  0xfe,0xdc,0xba,0x98, // H2
  0x76,0x54,0x32,0x10, // H3
  0xf0,0xe1,0xd2,0xc3  // H4
};

void Sha1Class::init(void) {
  memcpy_P(state.b,sha1InitState,HASH_LENGTH);
  byteCount = 0;
  bufferOffset = 0;
}

uint32_t Sha1Class::rol32(uint32_t number, uint8_t bits) {
  return ((number << bits) | (number >> (32-bits)));
}

void Sha1Class::hashBlock() {
  uint8_t i;
  uint32_t a,b,c,d,e,t;

  a=state.w[0];
  b=state.w[1];
  c=state.w[2];
  d=state.w[3];
  e=state.w[4];
  for (i=0; i<80; i++) {
    if (i>=16) {
      t = buffer.w[(i+13)&15] ^ buffer.w[(i+8)&15] ^ buffer.w[(i+2)&15] ^ buffer.w[i&15];
      buffer.w[i&15] = rol32(t,1);
    }
    if (i<20) {
      t = (d ^ (b & (c ^ d))) + SHA1_K0;
    } else if (i<40) {
      t = (b ^ c ^ d) + SHA1_K20;
    } else if (i<60) {
      t = ((b & c) | (d & (b | c))) + SHA1_K40;
    } else {
      t = (b ^ c ^ d) + SHA1_K60;
    }
    t+=rol32(a,5) + e + buffer.w[i&15];
    e=d;
    d=c;
    c=rol32(b,30);
    b=a;
    a=t;
  }
  state.w[0] += a;
  state.w[1] += b;
  state.w[2] += c;
  state.w[3] += d;
  state.w[4] += e;
}

void Sha1Class::addUncounted(uint8_t data) {
  buffer.b[bufferOffset ^ 3] = data;
  bufferOffset++;
  if (bufferOffset == BLOCK_LENGTH) {
    hashBlock();
    bufferOffset = 0;
  }
}

size_t Sha1Class::write(uint8_t data) {
  ++byteCount;
  addUncounted(data);
  return 1;
}

void Sha1Class::pad() {
  // Implement SHA-1 padding (fips180-2 §5.1.1)

  // Pad with 0x80 followed by 0x00 until the end of the block
  addUncounted(0x80);
  while (bufferOffset != 56) addUncounted(0x00);

  // Append length in the last 8 bytes
  addUncounted(0); // We're only using 32 bit lengths
  addUncounted(0); // But SHA-1 supports 64 bit lengths
  addUncounted(0); // So zero pad the top bits
  addUncounted(byteCount >> 29); // Shifting to multiply by 8
  addUncounted(byteCount >> 21); // as SHA-1 supports bitstreams as well as
  addUncounted(byteCount >> 13); // byte.
  addUncounted(byteCount >> 5);
  addUncounted(byteCount << 3);
}


uint8_t* Sha1Class::result(void) {
  // Pad to complete the last block
  pad();

  // Swap byte order back
  for (int i=0; i<5; i++) {
    uint32_t a,b;
    a=state.w[i];
    b=a<<24;
    b|=(a<<8) & 0x00ff0000;
    b|=(a>>8) & 0x0000ff00;
    b|=a>>24;
    state.w[i]=b;
  }

  // Return pointer to hash (20 characters)
  return state.b;
}

#define HMAC_IPAD 0x36
#define HMAC_OPAD 0x5c

void Sha1Class::initHmac(const uint8_t* key, int keyLength) {
  uint8_t i;
  memset(keyBuffer,0,BLOCK_LENGTH);
  if (keyLength > BLOCK_LENGTH) {
    // Hash long keys
    init();
    for (;keyLength--;) write(*key++);
    memcpy(keyBuffer,result(),HASH_LENGTH);
  } else {
    // Block length keys are used as is
    memcpy(keyBuffer,key,keyLength);
  }
  // Start inner hash
  init();
  for (i=0; i<BLOCK_LENGTH; i++) {
    write(keyBuffer[i] ^ HMAC_IPAD);
  }
}

uint8_t* Sha1Class::resultHmac(void) {
  uint8_t i;
  // Complete inner hash
  memcpy(innerHash,result(),HASH_LENGTH);
  // Calculate outer hash
  init();
  for (i=0; i<BLOCK_LENGTH; i++) write(keyBuffer[i] ^ HMAC_OPAD);
  for (i=0; i<HASH_LENGTH; i++) write(innerHash[i]);
  return result();
}
Sha1Class Sha1;

#include "calibrator.h"

void CameraCalibrator::addPoints(std::vector<cv::Point2f>& img_corners, std::vector<cv::Point3f>& obj_corners)
{
	image_points.push_back(img_corners);
	object_points.push_back(obj_corners);

	return;
}

int CameraCalibrator::add_chessboard_points(const std::vector<std::string>& filelist,
	cv::Size& board_size, bool visualize) {
	// the points on the chessboard
	std::vector<cv::Point2f> image_corners;
	std::vector<cv::Point3f> object_corners;

	// 3D Scene Points:
	// Initialize the chessboard corners
	// in the chessboard reference frame
	// The corners are at 3D location (X,Y,Z)= (i,j,0)
	for (int i = 0; i < board_size.height; i++)
		for (int j = 0; j < board_size.width; j++)
			object_corners.push_back(cv::Point3f(i, j, 0.0f));

	// 2D Image Points:
	cv::Mat image; // to contain chessboard image
	cv::Mat gray;
	int successes = 0;

	// for all viewpoints
	for (int i = 0; i < filelist.size(); i++) {
		// open the image
		image = cv::imread(filelist[i]);
		cv::cvtColor(image, gray, cv::COLOR_BGR2GRAY);

		// get the chessboard corners
		bool found = cv::findChessboardCorners(image, board_size, image_corners, CV_CALIB_CB_ADAPTIVE_THRESH | CV_CALIB_CB_FILTER_QUADS);
		// get subpixel accuracy on the corners
		if (found) {
			cv::cornerSubPix(gray, image_corners, cv::Size(5, 5),// half size of search window
				cv::Size(-1, -1),
				cv::TermCriteria(cv::TermCriteria::MAX_ITER +
					cv::TermCriteria::EPS, 30,// max number of iterations
					0.1)); //min accuracy
		}

		// if we have a good board, add it to our data
		if (image_corners.size() == board_size.area()) {
			// add image and scene points from one view
			addPoints(image_corners, object_corners);
			successes++;
		}

		//Draw the corners
		if (visualize) {
			cv::drawChessboardCorners(gray, board_size, image_corners, found);
			cv::imshow("Corners on Chessboard", image);
			cv::waitKey(1000);
		}
	}

	return successes;
}

double CameraCalibrator::calibrate(cv::Size& image_size)
{
	// Calibrate the camera
	// return the re-projection error
	// output rotations and translations
	std::vector<cv::Mat> rvecs, tvecs;

	// start calibration
	return cv::calibrateCamera(object_points,
		image_points,
		image_size,
		camera_matrix,
		dist_coeffs,
		rvecs, tvecs,
		flag);
}

// Set the calibration options
// 8radialCoeffEnabled should be true if 8 radial coefficients are required (5 is default)
// tangential_param_enabledshould be true if tangeantial distortion is present
void CameraCalibrator::set_calibration_flag(bool radial8_coeff_enabled, bool tangentialParamEnabled) {

	// Set the flag used in cv::calibrateCamera()
	flag = 0;
	if (!tangentialParamEnabled) flag += CV_CALIB_ZERO_TANGENT_DIST;
	if (radial8_coeff_enabled) flag += CV_CALIB_RATIONAL_MODEL;
}

cv::Mat CameraCalibrator::remap(const cv::Mat& image)
{
	cv::Mat undistorted;
	if (must_init_undistort) { // called once per calibration
		cv::initUndistortRectifyMap(
			camera_matrix, // computed camera matrix
			dist_coeffs, // computed distortion matrix
			cv::Mat(), // optional rectification (none)
			cv::Mat(), // camera matrix to generate undistorted
			image.size(), // size of undistorted
			CV_32FC1, // type of output map
			map1, map2); // the x and y mapping functions
		must_init_undistort = false;
	}
	// Apply mapping functions
	cv::remap(image, undistorted, map1, map2,
		cv::INTER_LINEAR); // interpolation type
	return undistorted;
}

void CameraCalibrator::show_undist_images(const std::vector<std::string>& filelist)
{
	cv::Mat image, undist_image;

	for (int i = 0; i < filelist.size(); i++) {
		// open the image
		image = cv::imread(filelist[i]);
		undist_image = remap(image);
		cv::imshow("Undistorted Image", undist_image);
		cv::waitKey(15000);
	}

	return;
}

void CameraCalibrator::save_as(std::string const& filename) const
{
	cv::FileStorage fs(filename, cv::FileStorage::WRITE);

	fs << "camera_matrix" << camera_matrix << "dist_coeffs" << dist_coeffs;
	fs << "map1" << map1 << "map2" << map2;
	fs << "must_init_undistort" << must_init_undistort;

	fs.release();

	return;
}

void CameraCalibrator::load_settings(std::string const& filename)
{
	cv::FileStorage fs(filename, cv::FileStorage::READ);

	fs["camera_matrix"] >> camera_matrix;
	fs["dist_coeffs"] >> dist_coeffs;
	fs["map1"] >> map1;
	fs["map2"] >> map2;
	fs["must_init_undistort"] >> must_init_undistort;

	fs.release();
	return;
}

