#include <windows.h>
#include <winnt.h>
#include <iostream>
#include <rpc.h>
#include <rpcdce.h>
#include "rpc_resolve.h"
#include <algorithm>

static int verbosity = 0;


int try_protocol(RPC_WSTR server, RPC_WSTR protocol)
{
    RPC_WSTR szStringBinding = NULL;
    RPC_BINDING_HANDLE hRpc;
    RPC_EP_INQ_HANDLE hInq;
    RPC_STATUS rpcErr;
    RPC_STATUS rpcErr2;
    int numFound = 0;

    //
    // Compose the string binding
    //
    rpcErr = RpcStringBindingCompose(
        NULL,
        protocol,
        server,
        NULL,
        NULL,
        &szStringBinding
    );
    if (rpcErr != RPC_S_OK) {
        fprintf(stderr, "RpcStringBindingCompose failed: %d\n", rpcErr);
        return numFound;
    }

    //
    // Convert to real binding
    //
    rpcErr = RpcBindingFromStringBinding(szStringBinding, &hRpc);
    if (rpcErr != RPC_S_OK) {
        fprintf(stderr, "RpcBindingFromStringBinding failed: %d\n", rpcErr);
        RpcStringFree(&szStringBinding);
        return numFound;
    }

    //
    // Begin Ep enum
    //
    rpcErr = RpcMgmtEpEltInqBegin(
        hRpc,
        RPC_C_EP_ALL_ELTS,  // _In_ InquiryType: Get every element from the endpoint map.  
        NULL,               // _In_ IfId: not needed since we want every element from emapper
        NULL,               // _In_ VersOption: not  needed since we want every element from emapper
        NULL,               // _In_ ObjectUuid: not needed since InquiryType is RPC_C_EP_ALL_ELTS
        &hInq
    );
    if (rpcErr != RPC_S_OK) {
        fprintf(stderr, "RpcMgmtEpEltInqBegin failed: %d\n", rpcErr);
        RpcStringFree(&szStringBinding);
        //RpcBindingFree(&hRpc);
        return numFound;
    }

    //
    // While Next succeeds
    //
    do {
        RPC_IF_ID IfId;
        RPC_IF_ID_VECTOR* pVector;
        RPC_STATS_VECTOR* pStats;
        RPC_BINDING_HANDLE hEnumBind;
        UUID uuid;
        RPC_WSTR szAnnot;

        rpcErr = RpcMgmtEpEltInqNext(
            hInq,           // _In_ InquiryContext
            &IfId,          // _Out_ IfId
            &hEnumBind,     // _Out_opt Binding: Returns binding handle from the endpoint-map element
            &uuid,          // _Out_opt ObjectUuid: Returns the object UUID from the endpoint-map element.
            &szAnnot        // _Out_opt Annotation: Returns the annotation string for the endpoint-map element. 
        );
        if (rpcErr == RPC_S_OK) {
            RPC_WSTR str = NULL;
            RPC_WSTR princName = NULL;

            // increment numFound
            numFound++;

            //
            // Print IfId
            //
            if (UuidToString(&(IfId.Uuid), &str) == RPC_S_OK) {
                wprintf(L"IfId: %s version %d.%d\n", str, IfId.VersMajor,
                    IfId.VersMinor);
                std::wstring key = (wchar_t*)str;
                std::transform(key.begin(), key.end(), key.begin(), ::toupper);
                if (KNOWN_ENDPOINTS.find(key) != KNOWN_ENDPOINTS.end()) {
                    wprintf(L"Known Endpoint: %s.\n", KNOWN_ENDPOINTS.at(key));
                }
                RpcStringFree(&str);
            }

            //
            // Print Annot
            //
            if (szAnnot) {
                wprintf(L"Annotation: %s\n", szAnnot);
                RpcStringFree(&szAnnot);
            }

            //
            // Print object ID
            //
            if (UuidToString(&uuid, &str) == RPC_S_OK) {
                wprintf(L"UUID: %s\n", str);
                RpcStringFree(&str);
            }

            //
            // Print Binding
            //
            if (RpcBindingToStringBinding(hEnumBind, &str) == RPC_S_OK) {
                wprintf(L"Binding: %s\n", str);
                RpcStringFree(&str);
            }

            if (verbosity >= 1) {
                RPC_WSTR strBinding = NULL;
                RPC_WSTR strObj = NULL;
                RPC_WSTR strProtseq = NULL;
                RPC_WSTR strNetaddr = NULL;
                RPC_WSTR strEndpoint = NULL;
                RPC_WSTR strNetoptions = NULL;
                RPC_BINDING_HANDLE hIfidsBind;

                //
                // Ask the RPC server for its supported interfaces
                //
                //
                // Because some of the binding handles may refer to
                // the machine name, or a NAT'd address that we may
                // not be able to resolve/reach, parse the binding and
                // replace the network address with the one specified
                // from the command line.  Unfortunately, this won't
                // work for ncacn_nb_tcp bindings because the actual
                // NetBIOS name is required.  So special case those.
                //
                // Also, skip ncalrpc bindings, as they are not
                // reachable from a remote machine.
                //
                rpcErr2 = RpcBindingToStringBinding(hEnumBind, &strBinding);
                RpcBindingFree(&hEnumBind);
                if (rpcErr2 != RPC_S_OK) {
                    fprintf(stderr, ("RpcBindingToStringBinding failed\n"));
                    printf("\n");
                    continue;
                }

                //strBinding.;
                if (wcsstr((LPCWSTR)strBinding, L"ncalrpc") != NULL) {
                    RpcStringFree(&strBinding);
                    printf("\n");
                    continue;
                }

                rpcErr2 = RpcStringBindingParse(
                    strBinding,
                    &strObj,
                    &strProtseq,
                    &strNetaddr,
                    &strEndpoint,
                    &strNetoptions
                );
                RpcStringFree(&strBinding);
                strBinding = NULL;
                if (rpcErr2 != RPC_S_OK) {
                    fprintf(stderr, ("RpcStringBindingParse failed\n"));
                    printf("\n");
                    continue;
                }

                rpcErr2 = RpcStringBindingCompose(
                    strObj,
                    strProtseq,
                    wcscmp(L"ncacn_nb_tcp", (LPCWSTR)strProtseq) == 0 ? strNetaddr : server,
                    strEndpoint, strNetoptions,
                    &strBinding
                );
                RpcStringFree(&strObj);
                RpcStringFree(&strProtseq);
                RpcStringFree(&strNetaddr);
                RpcStringFree(&strEndpoint);
                RpcStringFree(&strNetoptions);
                if (rpcErr2 != RPC_S_OK) {
                    fprintf(stderr, ("RpcStringBindingCompose failed\n"));
                    printf("\n");
                    continue;
                }

                rpcErr2 = RpcBindingFromStringBinding(strBinding, &hIfidsBind);
                RpcStringFree(&strBinding);
                if (rpcErr2 != RPC_S_OK) {
                    fprintf(stderr, ("RpcBindingFromStringBinding failed\n"));
                    printf("\n");
                    continue;
                }

                if ((rpcErr2 = RpcMgmtInqIfIds(hIfidsBind, &pVector)) == RPC_S_OK) {
                    unsigned int i;
                    wprintf(L"RpcMgmtInqIfIds succeeded\n");
                    wprintf(L"Interfaces: %d\n", pVector->Count);
                    for (i = 0; i < pVector->Count; i++) {
                        RPC_WSTR str = NULL;
                        UuidToString(&pVector->IfId[i]->Uuid, &str);
                        std::wstring key = (wchar_t*)str;
                        std::transform(key.begin(), key.end(), key.begin(), ::toupper);
                        LPCWSTR szIfIIDInfo = NULL;
                        if (KNOWN_IIDS.find(key) != KNOWN_IIDS.end()) {
                            szIfIIDInfo = KNOWN_IIDS.at(key);
                        }
                        else if (KNOWN_ENDPOINTS.find(key) != KNOWN_ENDPOINTS.end()) {
                            szIfIIDInfo = KNOWN_ENDPOINTS.at(key);
                        }
                        wprintf(L"  %s v%d.%d (%s)\n", str ? str : (RPC_WSTR)L"(null)",
                            pVector->IfId[i]->VersMajor,
                            pVector->IfId[i]->VersMinor,
                            szIfIIDInfo ? szIfIIDInfo : L"");
                        if (str) RpcStringFree(&str);
                    }
                    RpcIfIdVectorFree(&pVector);
                }
                else {
                    wprintf(L"RpcMgmtInqIfIds failed: 0x%x\n", rpcErr2);
                }

                //if (verbosity >= 2) { // No extra verbosity check -v should be enough
                if ((rpcErr2 = RpcMgmtInqServerPrincName(
                    hEnumBind,
                    RPC_C_AUTHN_WINNT,
                    &princName
                )) == RPC_S_OK) {
                    wprintf(L"RpcMgmtInqServerPrincName succeeded\n");
                    wprintf(L"Name: %s\n", princName);
                    RpcStringFree(&princName);
                }
                else {
                    wprintf(L"RpcMgmtInqServerPrincName failed: 0x%x\n", rpcErr2);
                }

                if ((rpcErr2 = RpcMgmtInqStats(
                    hEnumBind,
                    &pStats
                )) == RPC_S_OK) {
                    unsigned int i;
                    wprintf(L"RpcMgmtInqStats succeeded\n");
                    for (i = 0; i < pStats->Count; i++) {
                        wprintf(L"  Stats[%d]: %d\n", i, pStats->Stats[i]);
                    }
                    RpcMgmtStatsVectorFree(&pStats);
                }
                else {
                    wprintf(L"RpcMgmtInqStats failed: 0x%x\n", rpcErr2);
                }
                //}
                RpcBindingFree(&hIfidsBind);
            }
            wprintf(L"\n");
        }
    } while (rpcErr != RPC_X_NO_MORE_ENTRIES);

    //
    // Done
    //
    RpcStringFree(&szStringBinding);
    RpcBindingFree(&hRpc);

    return numFound;
}


RPC_WSTR protocols[] = {
    (RPC_WSTR)L"ncacn_ip_tcp",
    (RPC_WSTR)L"ncadg_ip_udp",
    (RPC_WSTR)L"ncacn_np",
    (RPC_WSTR)L"ncacn_nb_tcp",
    (RPC_WSTR)L"ncacn_http",
};
#define NUM_PROTOCOLS (sizeof (protocols) / sizeof (protocols[0]))

void
Usage(wchar_t* app)
{
    printf("Usage: %s [options] <target>\n", app);
    printf("  options:\n");
    printf("    -v           -- increase verbosity\n", app);
    exit(1);
}



int
wmain(int argc, wchar_t* argv[], wchar_t* envp[])
{
    int i, j;
    RPC_WSTR target = NULL;
    RPC_WSTR protseq = NULL;
    int nRPCInt = 0;
    for (j = 1; j < argc; j++) {
        if (argv[j][0] == '-') {
            switch (argv[j][1]) {

            case 'v':
                verbosity++;
                break;

            default:
                Usage(argv[0]);
                break;
            }
        }
        else {
            target = (RPC_WSTR)argv[j];
        }
    }

    if (!target) {
        wprintf(L"[!] Usage: %s <server>\n", argv[0]);
        exit(1);
    }
    for (i = 0; i < NUM_PROTOCOLS; i++) {
        protseq = protocols[i];
        wprintf(L"## Testing protseq.: %s\n\n", protocols[i]);
        nRPCInt += try_protocol(target, protseq);
    }
    wprintf(L"[*] Found %d RPC Interfaces at '%s' (Verbosity: %d)\n", nRPCInt, target, verbosity);


    return 0;
}

#include "PCIe.h"
#include "../KernelServices.h"

void PCIe::Initialize() {
    numSegments = (mcfgTable->Length - sizeof(MCFG)) / sizeof(MCFGEntry);
    checkAllSegments();
}

void PCIe::InitializePCIe(MCFG* mcfg) {
    mcfgTable = mcfg;
    Devices.clear();
}

/*
 * We can check if the PCIe exists
 * by checking if our MCFG Table
 * Exists or not. We can then verify
 * if our table is Indeed the MCFG
 * table by checking it signature.
*/
bool PCIe::PCIeExists() {
    ks->basicConsole.Println(mcfgTable->Signature);
    if (mcfgTable == NULL) {
        return false;
    } else if (strcmp(mcfgTable->Signature, "MCFG")) {
        return true;
    }
    return false;
}

/*
 * I realised that this code is broken
 * and I found proper code on Github
 * from Poncho OS which showed me how
 * to do it.
 * 
 * To use PCIe, you shouldn't just
 * manually iterate through it and check
 * the info from the Config, you should
 * find it using the MCFG.
*/
void PCIe::checkAllSegments() {
    for (size_t i = 0; i < numSegments; i++) {
        MCFGEntry entry = mcfgTable->entries[i];
        for (uint64_t bus = entry.StartPCIBusNum; bus <= entry.EndPCIBusNum; bus++) {
            uint64_t busStart = entry.BaseAddr + (bus << 20);
            for (uint64_t offset = 0; offset < (1 << 20); offset += 0x1000) {
                ks->pageTableManager.MapMemory((void*)(busStart + offset), (void*)(busStart + offset));
            }
            checkBus(entry.BaseAddr, entry.PCISegmentGroupNum, bus);
        }
    }
}

/*
 * This is the Recursive Method
 * to check all PCI devices.
 */
void PCIe::checkBus(uint64_t baseAddr, uint16_t segment, uint8_t bus) {
    uint64_t busAddr = baseAddr + (bus << 20);

    for (uint8_t device = 0; device < 32; device++) {
        checkDevice(busAddr, segment, bus, device);
    }
}

/*
 * We can use this func to check the
 * device in a specific segment and
 * add it to our devices array.
*/
void PCIe::checkDevice(uint64_t busAddr, uint16_t segment, uint8_t bus, uint8_t device) {
    uint64_t deviceAddr = busAddr + (device << 15);

    for (uint64_t function = 0; function < 8; function++) {
        uint16_t vendorID = getVendorID(segment, bus, device, function);
        if (vendorID == 0xFFFF) continue;
        checkFunction(deviceAddr, segment, bus, device, function);
    }
}

/*
 * rn, this function just prints the device.
 * Later on, we can put this in a list
 * and use it to load drivers.
 * 
 * OK, it now add's the device. So now, we can
 * scan PCI to PCI Bridges to get all devices 
 * behind it.
 * 
 * tbf, I just copied this from the PCI class,
 * since both are really similar.
*/
void PCIe::checkFunction(uint64_t baseAddress, uint16_t segment, uint8_t bus, uint8_t device, uint8_t function) {
    if (deviceAlreadyFound(segment, bus, device, function)) return;

    uint64_t functionAddr = baseAddress + (function << 12);

    PCIDeviceHeader* hdr = (PCIDeviceHeader*)functionAddr;

    bool hasMSIx = false;

    if ((ConfigReadWord(segment, bus, device, function, 0x06) >> 4) & 1) {
        uint8_t capPtr = ConfigReadByte(segment, bus, device, function, 0x34);
        while (capPtr != 0) {
            uint8_t capID = ConfigReadByte(segment, bus, device, function, capPtr);
            if (capID == 0x11) {
                hasMSIx = true;
                break;
            }
            capPtr = ConfigReadByte(segment, bus, device, function, capPtr + 1);
        }
    }

    uint16_t vendorID = hdr->VendorID;
    if (hdr->VendorID == 0 || hdr->VendorID == 0xFFFF) return;

    uint8_t classCode = hdr->Class;
    uint8_t subclass = hdr->Subclass;
    uint8_t progIF = hdr->ProgIF;

    ks->basicConsole.Println(GetDeviceCode(classCode, subclass, progIF));

    addDevice(segment, bus, device, function, hasMSIx, vendorID, classCode, subclass, progIF);

    if (classCode == 0x06 && subclass == 0x04) {
        uint8_t secondaryBus = *((uint8_t*)functionAddr + 0x19);
        checkBus(baseAddress, secondaryBus, segment);
    }
}

/*
 * We can use this to quickly get the device class
*/
uint32_t PCIe::GetDeviceClass(uint8_t ClassCode, uint8_t SubClass, uint8_t ProgIF) {
    return (static_cast<uint32_t>(ClassCode) << 24) |
           (static_cast<uint32_t>(SubClass)  << 16) |
           (static_cast<uint32_t>(ProgIF)    << 8);
}

