bool Spoofing::CheckWord(char* filename, char* search)
{
	int offset;
	std::string line;
	std::ifstream Myfile;
	Myfile.open(filename);

	if (Myfile.is_open())
	{
		while (!Myfile.eof())
		{
			getline(Myfile, line);
			if ((offset = line.find(search, 0)) != std::string::npos)
			{
				return true;
			}
		}
		Myfile.close();
	}

	return false;
}


